// Üretilen dosya: tool/ozgun/uret.py. Kimya · Periyodik özellikler ve elementler ayrıntılı (orta).
const ozChemistry7Orta = <(String, String, List<String>, String)>[
  ('Mendeleyev\'in \'eka-bor\' adıyla varlığını öngördüğü ve 1879\'da Lars Fredrik Nilson\'un bulduğu element hangisidir?', 'Skandiyum', ['Germanyum', 'Galyum', 'Teknesyum elementi'], 'Mendeleyev borun altındaki boşluğa eka-bor dedi; bu boşluğu 1879\'da bulunan skandiyum doldurdu.'),
  ('Mendeleyev eka-silisyumun yoğunluğunu yaklaşık 5,5 g/cm³ olarak öngörmüştü; germanyumun ölçülen yoğunluğu yaklaşık 5,35 g/cm³ çıktı. Bu uyum bilimsel yöntem açısından neyi gösterir?', 'Bir kuramın sınanabilir tahminlerinin doğrulanmasını', ['Ölçümlerin her zaman kuramdan önce yapılması gerektiğini', 'Yoğunluğun periyodik bir özellik olmadığını', 'Elementlerin atom numarasıyla sıralandığını'], 'Kuramın önceden yaptığı nicel tahminin deneyle doğrulanması, periyodik yasanın gücünü gösteren klasik bir örnektir.'),
  ('Lavoisier\'nin 1789\'da yayımladığı 33 \'basit madde\' listesinde bugün element sayılmayan hangi kavram da yer alıyordu?', 'Kalorik (ısı maddesi)', ['Kükürt', 'Fosfor', 'Cıva (hidrargirum)'], 'Lavoisier listesine ışık ve kaloriği de koymuştu; ısının bir madde olduğu görüşü daha sonra terk edildi. Kükürt, fosfor ve cıva gerçekten elementtir.'),
  ('Atom kütlesine göre sıralandığında argon (39,95) potasyumdan (39,10) sonra gelmelidir. Modern periyodik sistemde argonun potasyumdan önce yer almasının gerekçesi nedir?', 'Argonun atom numarasının potasyumunkinden küçük olması', ['Argonun doğada çok daha fazla sayıda izotopa sahip olması', 'Potasyumun daha yoğun bir metal olması', 'Argonun Mendeleyev\'den sonra keşfedilmesi'], 'Modern sistemde sıralama atom numarasına göredir: Ar (Z = 18), K (Z = 19). Kütledeki ters durum izotop bolluklarından kaynaklanır.'),
  ('Argonu Lord Rayleigh ile birlikte bulan, ardından neon, kripton ve ksenonu da keşfederek tabloya yeni bir grup ekleyen İskoç kimyacı kimdir?', 'William Ramsay', ['John Dalton', 'Ernest Rutherford', 'Humphry Davy'], 'William Ramsay soy gazları bulduğu çalışmalarla 1904 Nobel Kimya Ödülü\'nü aldı.'),
  ('Mendeleyev\'in özgün periyodik yasası ile modern periyodik yasa arasındaki temel fark hangisidir?', 'Özelliklerin kütleye değil atom numarasına bağlı olarak yinelenmesi', ['Modern yasanın yalnız metalleri ve onların bileşiklerini kapsaması', 'Özgün yasanın elektron dizilimine dayanması', 'Modern yasada grupların kaldırılması'], 'Mendeleyev özellikleri atom kütlesinin periyodik fonksiyonu sayıyordu; modern yasa atom numarasını esas alır.'),
  ('Eski Amerikan gösteriminde \'IIIA\' olarak adlandırılan grup, IUPAC\'ın 1\'den 18\'e numaralandırmasında kaçıncı gruptur?', '13', ['3', '11', '15'], 'A grupları s ve p blokunu gösterir: IA=1, IIA=2, IIIA=13, IVA=14, VA=15, VIA=16, VIIA=17, VIIIA=18.'),
  ('Eski A/B gösteriminde \'IB\' grubu olarak anılan ve bakır, gümüş, altını içeren grup IUPAC numaralandırmasında hangisidir?', '11. grup', ['1. grup', '9. grup', '12. grup'], 'IB, d blokunun 11. sütunudur; IIB ise 12. gruba (Zn, Cd, Hg) karşılık gelir.'),
  ('Modern periyodik sistemde toplam 118 element bulunur. Bunlardan kaçı 7. periyottadır?', '32', ['18', '28', '14'], '7. periyot fransiyumdan (87) oganessona (118) kadar uzanır: 118 − 86 = 32 element.'),
  ('Lantanitler ve aktinitler ana tablonun içine yerleştirilerek çizilen ve 32 sütundan oluşan tablo biçimine ne ad verilir?', 'Uzun biçimli periyodik tablo', ['Kısa biçimli periyodik tablo', 'Sarmal periyodik tablo', 'Döbereiner\'in üçlüler tablosu'], '32 sütunlu uzun biçimde f bloku ayrı sıra olarak değil, ana tabloda yer alır; standart 18 sütunlu tablo yer tasarrufu sağlar.'),
  ('Değerlik katmanı dizilimi 4s² 4p³ olan bir element hakkında hangisi doğrudur?', '4. periyot, 15. grupta yer alan bir p bloku elementidir', ['4. periyot, 5. grupta yer alan bir d bloku geçiş elementidir', '3. periyot, 15. grupta yer alan bir p bloku elementidir', '4. periyot, 13. grupta yer alan bir p bloku elementidir'], 'Baş kuantum sayısı periyodu (4), p bloku için 10 + s ve p elektronları toplamı grubu verir: 10 + 5 = 15.'),
  ('Değerlik elektronları 5s² 4d² olan element periyodik sistemde nerededir?', '5. periyot, 4. grup', ['4. periyot, 2. grup', '5. periyot, 14. grup', '4. periyot, 4. grup'], 'En yüksek baş kuantum sayısı 5 olduğundan 5. periyottadır; d bloku için grup = s + d elektronları = 4. Bu element zirkonyumdur.'),
  ('5. periyodun 17. grubunda yer alan elementin atom numarası kaçtır?', '53', ['35', '85', '51'], '5. periyot Z = 37\'de başlar; 17. grup 18. grubun (Z = 54, ksenon) hemen solundadır: 53 (iyot).'),
  ('Atom numarası 56 olan element için hangisi doğrudur?', '6. periyot, 2. grupta bir s bloku elementidir', ['5. periyot, 2. grupta bir s bloku elementidir', '6. periyot, 3. grupta bir f bloku elementidir', '6. periyot, 12. grupta bir d bloku elementidir'], 'Z = 54 (ksenon) 5. periyodu bitirir; 55 sezyum ve 56 baryum 6s alt katmanını doldurur.'),
  ('Hidrojenin bazı periyodik tablolarda 17. grubun üzerinde de gösterilmesinin dayanağı hangisidir?', 'Bir elektron alarak hidrür iyonu (H⁻) oluşturabilmesi', ['Oda koşullarında renkli bir gaz olması', 'Bileşiklerinde her zaman yalnızca +1 değerlik alması', 'Suyla tepkimeye girip baz oluşturması'], 'Hidrojen, halojenler gibi soy gaz dizilimine bir elektron uzaktadır ve aktif metallerle NaH gibi hidrürler oluşturur.'),
  ('Hidrojenin 1. grup metalleriyle aynı grupta sayılmamasının en güçlü gerekçesi hangisidir?', 'Olağan koşullarda metalik özellik göstermeyen iki atomlu bir gaz olması', ['Tek değerlik elektronu bulunması', 'Bileşiklerinde +1 yükseltgenme basamağı alabilmesi ve iyon vermesi', 'Atom numarasının 1 olması'], 'Değerlik dizilimi 1s¹ olsa da hidrojen olağan koşullarda H₂ moleküllerinden oluşan bir ametaldir; diğer seçenekler aksine benzerlik gerekçesidir.'),
  ('Alkali metaller arasında oda sıcaklığında azot gazıyla doğrudan tepkimeye girerek nitrür oluşturan tek element hangisidir?', 'Lityum', ['Sezyum', 'Sodyum', 'Rubidyum'], 'Lityum havadaki azotla tepkimeye girip Li₃N oluşturur; bu davranış magnezyuma benzerliğinin bir göstergesidir.'),
  ('İki uçlu bozukluk (manik depresif hastalık) tedavisinde ruh durumu dengeleyici olarak kullanılan ilacın etkin elementi hangisidir?', 'Lityum', ['Potasyum', 'Magnezyum', 'Sezyum'], 'Lityum karbonat gibi lityum tuzları duygudurum dengeleyici olarak 20. yüzyılın ortasından beri kullanılır.'),
  ('Bazı hızlı üreteç nükleer reaktörlerde sıvı sodyumun soğutucu olarak kullanılmasının nedeni hangisidir?', 'Isıyı çok iyi iletmesi ve geniş sıcaklık aralığında sıvı kalması', ['Nötronları tümüyle soğurması', 'Suyla tepkimeye hiç girmemesi', 'Radyoaktif olması ve reaktörde kendiliğinden ısı üretmesi'], 'Sodyum yaklaşık 98 °C\'de erir, 883 °C\'de kaynar ve mükemmel bir ısı iletkenidir; suyla şiddetli tepkimesi ise bir güvenlik sorunudur.'),
  ('Doğal potasyumun küçük bir kısmını oluşturan ve insan vücudundaki doğal radyoaktivitenin önemli bir kaynağı olan izotop hangisidir?', 'Potasyum-40', ['Potasyum-39', 'Potasyum-41', 'Potasyum-38'], 'K-40 yaklaşık 1,25 milyar yıl yarı ömürlü, doğal radyoaktif bir izotoptur; potasyum-argon tarihlendirmesinde de kullanılır.'),
  ('Erime noktası yaklaşık 28 °C olan ve sıcak bir yaz gününde sıvılaşabilecek alkali metal hangisidir?', 'Sezyum', ['Lityum', 'Sodyum', 'Potasyum'], 'Sezyum yaklaşık 28,5 °C\'de erir; lityum 181, sodyum 98, potasyum 63 °C\'de erir.'),
  ('Bir öğrenci sodyumun yoğunluğunun (0,97 g/cm³) potasyumunkinden (0,86 g/cm³) büyük olmasını \'grupta aşağı yoğunluk hep artar\' kuralına aykırı buluyor. Hangi değerlendirme doğrudur?', 'Alkali metallerde yoğunluk genel olarak artsa da bu çiftte bir düzensizlik vardır', ['Ölçümlerden biri mutlaka hatalı olmalıdır', 'Potasyum sodyumun üstünde yer aldığı için bu durum normaldir', 'Yoğunluk atom numarasıyla her zaman doğru orantılı olarak artar'], 'Yoğunluk kütle ile hacmin birlikte değişmesine bağlıdır; K\'de hacim artışı kütle artışını geçtiği için sodyumdan hafif olur.'),
  ('Sofra tuzunun iyotlanmasında genellikle hangi bileşik eklenir?', 'Potasyum iyodat ya da potasyum iyodür', ['Sodyum florür', 'Kalsiyum karbonat', 'Magnezyum sülfat heptahidrat'], 'Guatr gibi iyot eksikliği hastalıklarını önlemek için tuza KIO₃ ya da KI eklenir.'),
  ('Hidrojen atomu elektronunu verdiğinde geride kalan tanecik için hangisi doğrudur?', 'Yalnız bir protondan oluşan çok küçük bir çekirdektir', ['Bir nötron ve bir protondan oluşan bir döteryum çekirdeğidir', 'Helyum çekirdeğine eşdeğerdir', 'Elektron dizilimi neonla aynıdır'], 'Protiyum atomu elektronunu kaybedince çıplak proton kalır; bu yüzden H⁺ sulu ortamda tek başına bulunmaz, su moleküllerine bağlanır.'),
  ('Berilyumun röntgen tüplerinin pencerelerinde kullanılmasının nedeni hangisidir?', 'Düşük atom numarası nedeniyle X ışınlarını çok az soğurması', ['Çok yüksek yoğunluklu olduğu için ışınları tek bir noktaya odaklaması', 'X ışınlarını görünür ışığa çeviren parlak bir metal olması', 'Radyoaktif olup ek ışınım üretmesi'], 'Hafif atomlar X ışınlarını az soğurur; berilyum hem hafif hem de sağlam olduğu için ideal pencere malzemesidir.'),
  ('2. grup elementleri arasında hidroksidi amfoter olan, yani hem asitlerle hem kuvvetli bazlarla tepkimeye giren element hangisidir?', 'Berilyum', ['Kalsiyum', 'Magnezyum', 'Stronsiyum'], 'Be(OH)₂ amfoterdir; grubun diğer hidroksitleri baziktir. Bu durum küçük ve yüksek yük yoğunluklu Be²⁺ iyonundan kaynaklanır.'),
  ('Halk arasında \'İngiliz tuzu\' olarak bilinen ve müshil olarak da kullanılan bileşik hangisidir?', 'Magnezyum sülfat heptahidrat', ['Sodyum klorür', 'Kalsiyum sülfat dihidrat', 'Potasyum alüminyum sülfat'], 'İngiliz tuzu (Epsom tuzu) MgSO₄·7H₂O\'dur; adını İngiltere\'deki Epsom kaynaklarından alır.'),
  ('Alçı taşının (jips) kimyasal formülü hangisidir?', 'CaSO₄·2H₂O', ['CaCO₃', 'Ca(OH)₂', 'MgSO₄·7H₂O'], 'Jips kalsiyum sülfat dihidrattır; ısıtılınca suyunun bir kısmını kaybederek inşaat alçısına dönüşür.'),
  ('Nükleer kazalardan sonra stronsiyum-90\'ın özellikle tehlikeli sayılmasının nedeni hangisidir?', 'Kalsiyuma benzediği için kemiklerde birikmesi', ['Soy gaz olduğu için kolayca solunması', 'Yarı ömrünün birkaç saniye olması', 'Suda hiç çözünmediği için toprakta uzun süre değişmeden kalması'], 'Sr²⁺ ile Ca²⁺ aynı gruptadır; vücut stronsiyumu kalsiyum gibi kemiğe yerleştirir ve yaklaşık 29 yıl yarı ömürlü Sr-90 orada ışınım yapar.'),
  ('20. yüzyılın başında saat kadranlarının karanlıkta parlaması için kullanılan ve bu boyaları sürenlerde ağır hastalıklara yol açan element hangisidir?', 'Radyum', ['Fosfor', 'Neon', 'Baryum'], 'Radyumlu boyalar ışıldıyordu; fırçalarını dudaklarıyla sivrilten işçilerde (\'radyum kızları\') ağır kemik hasarları görüldü.'),
  ('2. grup elementlerinin hidroksitlerinin sudaki çözünürlüğü magnezyumdan baryuma doğru nasıl değişir?', 'Artar', ['Azalır', 'Önce azalır, sonra artar', 'Değişmez'], 'Mg(OH)₂ çok az çözünürken Ba(OH)₂ oldukça çözünürdür; bu yüzden baryum hidroksit çözeltisi kuvvetli bazdır.'),
  ('2. grup sülfatlarının çözünürlüğü için hangisi doğrudur?', 'MgSO₄ suda iyi çözünür, BaSO₄ ise neredeyse hiç çözünmez', ['BaSO₄ suda en çok çözünen sülfattır', 'Grupta aşağı inildikçe sülfat çözünürlüğü düzenli olarak artar', 'Dört sülfatın çözünürlüğü birbirine eşittir'], 'Sülfat çözünürlüğü grupta aşağı doğru azalır; hidroksitlerdeki eğilimin tersidir.'),
  ('\'Toprak alkali\' adındaki \'toprak\' sözcüğü eski kimyacıların hangi gözlemine dayanır?', 'Oksitlerinin ısıya dayanıklı ve suda az çözünen toprak benzeri maddeler olması', ['Yalnızca toprağın altında saf metal olarak bulunmaları', 'Toprağı yeşile boyamaları', 'Topraktaki suyu buharlaştırmaları'], 'Eski kimyada ısıyla değişmeyen, suda az çözünen oksitlere \'toprak\' denirdi; bu oksitler aynı zamanda bazik (alkali) özellik gösterir.'),
  ('2. grup metallerinin birinci iyonlaşma enerjileri, aynı periyottaki 1. grup metallerininkinden neden yüksektir?', 'Çekirdek yükü artarken s elektronunun aynı katmanda kalması', ['2. grup metallerinin daha büyük atom yarıçapına sahip olması', '2. grup elementlerinin ametal olması', '1. grup metallerinin daha fazla değerlik elektronu bulunması'], 'Aynı periyotta bir proton fazla olan 2. grup atomunda dış elektron daha güçlü çekilir ve atom daha küçüktür.'),
  ('Bir öğrenci baryumun magnezyumdan daha aktif bir metal olduğunu öne sürüyor. Bu iddiayı en iyi destekleyen veri hangisidir?', 'Baryumun birinci ve ikinci iyonlaşma enerjileri toplamının daha düşük olması', ['Baryumun yoğunluğunun daha yüksek olması', 'Magnezyumun daha parlak bir alevle yanması', 'Baryumun daha büyük atom kütlesine ve daha çok nötrona sahip olması'], 'Toprak alkali metaller M²⁺ iyonu oluşturur; iki elektronu koparmak için gereken toplam enerji baryumda çok daha düşüktür.'),
  ('Bor, 13. grubun diğer elementlerinden farklı olarak metalik özellik göstermez. Bunun temel nedeni hangisidir?', 'Atomunun çok küçük, iyonlaşma enerjisinin yüksek olması', ['Değerlik elektron sayısının alüminyumdan çok daha fazla olması', 'Doğada yalnızca gaz hâlinde bulunması', 'Çekirdeğinde nötron bulunmaması'], 'B³⁺ iyonu oluşturmak çok fazla enerji gerektirdiğinden bor, elektronlarını vermek yerine kovalent bağlar kurar.'),
  ('Bitkiler için mikro besin öğesi olan, eksikliğinde büyüme noktalarının ve çiçeklenmenin bozulduğu yarı metal hangisidir?', 'Bor', ['Silisyum', 'Arsenik', 'Germanyum'], 'Bor hücre duvarı yapısı ve polen gelişimi için gerekli bir eser elementtir; fazlası da bitkilere zehirlidir.'),
  ('Bor içeren bir bileşik metanolle karıştırılıp yakıldığında alevin rengi hangisi olur?', 'Yeşil', ['Mor', 'Sarı', 'Kırmızı'], 'Borik asidin metanolle oluşturduğu uçucu trimetil borat aleve parlak yeşil renk verir; bu test bor tanımada kullanılır.'),
  ('Hall-Héroult yönteminin bulunmasından önce, 19. yüzyılın ortalarında alüminyumun çok pahalı bir metal olmasının nedeni hangisidir?', 'Oksidinden metale indirgenmesinin çok zor olması', ['Yer kabuğunda çok az bulunması', 'Yalnız göktaşlarında ve meteor kraterlerinde bulunması', 'Havada kendiliğinden tutuşması'], 'Alüminyum bol olsa da oksijene çok sıkı bağlıdır; karbonla indirgenemez ve elektroliz yöntemi bulunana dek pahalı kimyasal yöntemlerle üretiliyordu.'),
  ('Hurda alüminyumun geri dönüştürülmesi, cevherden yeni alüminyum üretimine göre neden çok daha az enerji gerektirir?', 'Metalin oksitten indirgenmesi gerekmez, yalnız eritilmesi yeterlidir', ['Hurda alüminyum zaten sıvı hâlde bulunur', 'Geri dönüşümde elektroliz yerine radyasyon kullanılır', 'Hurda alüminyumun erime noktası cevherinden elde edilen metalinkinden çok yüksektir'], 'Elektrolizin büyük enerji gereksinimi atlanır; geri dönüşüm, birincil üretim enerjisinin yalnızca küçük bir kısmını harcar.'),
  ('Galyum ve suyun ortak olağandışı özelliği hangisidir?', 'Katılaşırken hacimlerinin artması', ['Oda sıcaklığında gaz olmaları', 'Elektriği hiç iletmemeleri', 'Kaynarken renk değiştirip mor buhar oluşturmaları'], 'Galyum, bizmut ve su gibi az sayıda maddenin katısı sıvısından daha az yoğundur; bu yüzden galyum cam kapta donarsa kabı çatlatabilir.'),
  ('Dokunmatik ekranlarda ve düz panel göstergelerde saydam iletken kaplama olarak kullanılan indiyum bileşiği hangisidir?', 'İndiyum kalay oksit', ['İndiyum klorür', 'İndiyum fosfat', 'İndiyum galyum arsenür'], 'İndiyum kalay oksit (ITO) hem görünür ışığı geçirir hem de elektriği iletir; bu ender özellik onu ekranlar için vazgeçilmez kılar.'),
  ('Alüminyumun, metallerin elektrik iletkenliğinde bakırın gerisinde kalmasına karşın yüksek gerilim hatlarında tercih edilmesinin nedeni hangisidir?', 'Kütlesine göre iletkenliğinin yüksek ve fiyatının düşük olması', ['Bakırdan daha iyi bir iletken olması', 'Hiç ısınmadan ve kayıpsız akım iletebilmesi', 'Mıknatısa güçlü biçimde çekilmesi'], 'Alüminyumun yoğunluğu bakırın yaklaşık üçte biridir; aynı kütlede daha fazla akım taşır ve uzun hatlarda direklere daha az yük biner.'),
  ('Grafeni grafitten ayırarak 2010 Nobel Fizik Ödülü\'nü paylaşan iki bilim insanı kimlerdir?', 'Andre Geim ve Konstantin Novoselov', ['Harold Kroto ve Richard Smalley', 'Pierre Curie ve Marie Skłodowska-Curie', 'Walter Kohn ve John Pople'], 'Geim ve Novoselov 2004\'te grafit üzerinden yapışkan bantla tek katmanlı grafen elde etmişti.'),
  ('Saf silisyum sanayide başlıca hangi tepkimeyle elde edilir?', 'Kumdaki silisyum dioksitin elektrik ark fırınında karbonla indirgenmesi', ['Silisyum klorürün suyla tepkimesi', 'Kumun yüksek basınçta ve yüksek sıcaklıkta suyla saatlerce kaynatılması', 'Silikon kauçuğun yakılması'], 'SiO₂ + 2C → Si + 2CO tepkimesiyle metalurjik silisyum elde edilir; elektronik için ayrıca saflaştırılır.'),
  ('Bilgisayar çipleri için gereken çok saf tek kristal silisyum hangi yöntemle büyütülür?', 'Czochralski yöntemi', ['Haber-Bosch yöntemi', 'Solvay yöntemi', 'Ostwald yöntemi ve damıtma'], 'Czochralski yönteminde erimiş silisyuma daldırılan bir tohum kristal yavaşça döndürülerek çekilir ve büyük tek kristal külçe elde edilir.'),
  ('Kuvars saatlerde doğru zaman tutulmasını sağlayan özellik hangisidir?', 'Kuvars kristalinin gerilimle belirli bir frekansta titreşmesi', ['Kuvarsın radyoaktif bozunma yapması', 'Kuvarsın ışığı ikiye ayırması', 'Kuvarsın güçlü bir kalıcı mıknatıs özelliği taşıyıp akım üretmesi'], 'Kuvars piezoelektriktir; elektrik alanda kararlı bir frekansta titreşir ve bu titreşim saat devresince sayılır.'),
  ('Germanyumun günümüzdeki önemli kullanım alanlarından biri hangisidir?', 'Kızılötesi optik mercekler ve fiber optik camlar', ['Mutfak tuzu üretimi', 'Diş macunu katkısı', 'Balon ve hava gemisi dolgu gazı olarak kullanılması'], 'Germanyum kızılötesi ışığı geçirdiği için gece görüş cihazlarında mercek olarak, GeO₂ ise fiber optik camlarda kullanılır.'),
  ('Kurşunun simgesindeki \'Pb\'nin kaynağı olan Latince plumbum sözcüğü, İngilizcede hangi meslek adına da kök olmuştur?', 'Tesisatçı (plumber)', ['Demirci (blacksmith)', 'Fırıncı (baker)', 'Kuyumcu (goldsmith)'], 'Romalılar su borularını kurşundan yaptığı için boru işçiliği plumbum\'dan türeyen sözcüklerle anılır.'),
  ('Kalayın erime noktası yaklaşık kaç °C\'dir?', '232', ['1085', '660', '1538'], 'Kalay 232 °C\'de erir; 1085 bakırın, 660 alüminyumun, 1538 demirin erime noktasıdır.'),
  ('C (elmas), Si, Ge ve Pb arasında oda koşullarında elektriği en iyi ileten hangisidir?', 'Pb', ['Si', 'Ge', 'C'], 'Kurşun bir metaldir; Si ve Ge yarı iletken, elmas ise yalıtkandır. Grupta aşağı inildikçe metalik karakter ve iletkenlik artar.'),
  ('Lavoisier\'nin azota verdiği ve Türkçedeki \'azot\' adının da kaynağı olan \'azote\' sözcüğü hangi anlamı taşır?', 'Yaşamı desteklemeyen', ['Tuz oluşturan', 'Asit yapan madde', 'Işık taşıyan ve parlayan'], 'Yunanca kökenli \'a-zoe\' yaşam yok anlamına gelir; saf azotta canlılar boğulur ve mum söner.'),
  ('Fosforun allotropları arasında en kararlı olanı ve katmanlı yapısıyla grafite benzeyen hangisidir?', 'Siyah fosfor', ['Beyaz fosfor', 'Kırmızı fosfor', 'Sarı fosfor'], 'Siyah fosfor yüksek basınçta elde edilir, en az etkin allotroptur ve katmanlı yapısı nedeniyle yarı iletkendir.'),
  ('Süperfosfat gübresi hangi doğal hammaddenin sülfürik asitle işlenmesiyle üretilir?', 'Fosfat kayası (kalsiyum fosfat mineralleri)', ['Kireç taşı (kalsiyum karbonat)', 'Kaya tuzu (sodyum klorür)', 'Boksit (alüminyum oksit hidrat mineralleri)'], 'Suda çözünmeyen Ca₃(PO₄)₂, sülfürik asitle bitkilerin alabileceği çözünür kalsiyum dihidrojen fosfata dönüştürülür.'),
  ('Gri arsenik 1 atm basınçta ısıtıldığında erimeden gaza dönüşür. Bu davranış hangi olaydır?', 'Süblimleşme', ['Kırağılaşma', 'Buharlaşma', 'Yoğunlaşma'], 'Arseniğin üçlü noktasındaki basınç 1 atm\'den yüksektir; bu yüzden olağan basınçta yaklaşık 615 °C\'de süblimleşir.'),
  ('Antik Mısır\'da göz çevresine sürülen \'kohl\' (sürme) boyasında kullanılan siyah mineral stibnit, hangi elementin sülfürüdür?', 'Antimon', ['Bizmut', 'Arsenik', 'Demir'], 'Stibnit Sb₂S₃\'tür; antimonun Sb simgesi de Latince stibium adından gelir.'),
  ('Eski matbaa harflerinin yapıldığı kurşun alaşımına antimon eklenmesinin bir amacı hangisidir?', 'Alaşımı sertleştirmek ve katılaşırken hafifçe genleşmesini sağlamak', ['Alaşımı oda sıcaklığında sıvı hâle getirmek', 'Harfleri radyoaktif yapmak', 'Harflerin rengini altın sarısına çevirip baskıyı parlatmak ve süslemek'], 'Antimon kurşunu sertleştirir ve katılaşırken genleşmesi sayesinde harf kalıbının ince ayrıntılarını doldurur.'),
  ('Mide bulantısı ve ishal için kullanılan bazı ilaçlarda etkin madde olarak bulunan bizmut bileşiği hangisidir?', 'Bizmut subsalisilat', ['Bizmut nitrat pentahidrat', 'Bizmut tellürür', 'Bizmut germanat'], 'Bizmut subsalisilat mide-bağırsak yakınmalarında kullanılır; fazla kullanımı dilin kararmasına yol açabilir.'),
  ('Laboratuvarda büyütülen bizmut kristallerinin gökkuşağı renklerinde parlamasının nedeni hangisidir?', 'Yüzeydeki ince oksit tabakasında ışığın girişimi', ['Kristalin içindeki boya katkıları', 'Bizmutun radyoaktif ışıması', 'Kristalin elektrik akımıyla uyarılıp kendi ışığını üretmesi'], 'Oksit tabakasının kalınlığı değiştikçe farklı dalga boyları güçlenir; renkler sabun köpüğündeki gibi girişimden doğar.'),
  ('Azotun bileşiklerinde görülen en düşük ve en yüksek yükseltgenme basamakları hangileridir?', '−3 ve +5', ['−2 ve +6', '−1 ve +7', '0 ve +4'], 'Azot NH₃\'te −3, HNO₃\'te +5 basamağındadır; 5 değerlik elektronu bu aralığı belirler.'),
  ('Oksijeni birbirinden bağımsız olarak 1770\'lerde bulan iki bilim insanı hangileridir?', 'Carl Wilhelm Scheele ve Joseph Priestley', ['Robert Boyle ve Isaac Newton', 'John Dalton ve Amedeo Avogadro', 'Humphry Davy ve Michael Faraday ile Joseph Black'], 'Scheele oksijeni muhtemelen 1771-72\'de elde etti ama sonuçlarını geç yayımladı; Priestley 1774\'te cıva oksidi ısıtarak buldu.'),
  ('Ozonun adı Yunancada hangi anlama gelen sözcükten türetilmiştir?', 'Koklamak', ['Mavi renkli', 'Gökyüzü', 'Üçlü'], 'Ozon, fotokopi makineleri yakınında ve şimşekten sonra hissedilen keskin kokusuyla tanınır; adı \'ozein\' (koklamak) sözcüğünden gelir.'),
  ('Oksijen bileşiklerinin çoğunda −2 yükseltgenme basamağı alırken OF₂ bileşiğinde +2 basamağındadır. Bunun nedeni hangisidir?', 'Florun oksijenden daha elektronegatif olması', ['Oksijenin bu bileşikte metal gibi davranması', 'OF₂\'nin tamamen iyonik bir kristal bileşik olması', 'Florun bu bileşikte +1 değerlik alması'], 'Bağ elektronları daha elektronegatif olan flora sayıldığı için her F −1, oksijen ise +2 olur.'),
  ('Kükürdün iki katı allotropu olan rombik ve monoklinik kükürtle ilgili hangisi doğrudur?', 'Oda sıcaklığında rombik, yaklaşık 96 °C\'nin üzerinde monoklinik biçim kararlıdır', ['İkisi de yalnız sıvı hâlde bulunur', 'Monoklinik biçim oda sıcaklığında, rombik biçim yalnızca kaynama noktasında kararlıdır', 'İkisi farklı elementlerdir'], 'Kükürt 95,5 °C civarında rombikten monoklinik yapıya geçer; ikisi de S₈ halkalarından oluşur ama halkaların diziliş biçimi farklıdır.'),
  ('Yer altındaki kükürt yataklarına aşırı ısıtılmış su basılarak kükürdün eritilip yüzeye çıkarıldığı yöntem hangisidir?', 'Frasch yöntemi', ['Kontakt yöntemi', 'Bayer yöntemi', 'Mond yöntemi'], 'Kükürdün erime noktası yaklaşık 115 °C olduğundan basınçlı sıcak suyla eritilip hava ile yüzeye pompalanabilir.'),
  ('Selenyumun ilk fotokopi makinelerinde (kserografi) kullanılmasını sağlayan özelliği hangisidir?', 'Işık altında elektrik iletkenliğinin büyük ölçüde artması', ['Karanlıkta parlaması', 'Mıknatısa güçlü biçimde çekilmesi', 'Oda sıcaklığında sıvı olması ve kâğıdın yüzeyine kolayca yayılarak iz bırakması'], 'Selenyum ışık iletkendir (fotoiletken); ışık düşen yerlerde yük boşalır ve toner yalnız karanlık kalan bölgelere tutunur.'),
  ('Adı Ay\'ı simgeleyen Yunanca bir sözcükten gelen element selenyumdur. Selenyumun hemen altında yer alan ve adı Latincede \'Dünya\' anlamına gelen element hangisidir?', 'Tellür', ['Toryum', 'Polonyum', 'Uranyum'], 'Tellür adını Latince tellus (yer, Dünya) sözcüğünden alır; Berzelius, tellüre benzeyen yeni elemente bu yüzden Ay\'ın adını verdi.'),
  ('İnsan vücudunda glutatyon peroksidaz gibi antioksidan enzimlerin yapısında bulunan, eksikliği de fazlası da zararlı olan eser element hangisidir?', 'Selenyum', ['Kurşun', 'Tellür', 'Arsenik'], 'Selenyum selenosistein amino asidi olarak bazı enzimlere katılır; günlük gereksinim mikrogram düzeyindedir ve fazlası zehirlidir.'),
  ('İnce film güneş panellerinde kadmiyumla birlikte yarı iletken bileşik olarak kullanılan 16. grup elementi hangisidir?', 'Tellür', ['Oksijen', 'Kükürt', 'Polonyum'], 'Kadmiyum tellürür (CdTe) güneş ışığını verimli soğuran bir yarı iletkendir ve ince film panellerde yaygındır.'),
  ('16. grupta oksijenden polonyuma doğru elementlerin sınıfı nasıl değişir?', 'Oksijen, kükürt ve selenyum ametal; tellür yarı metal; polonyum metalik karakterlidir', ['Beşi de ametaldir', 'Oksijen metal, diğerleri ametaldir', 'Oksijen ve kükürt yarı metal; selenyum, tellür ve polonyum ise kararlı soy gazlardır'], 'Grupta aşağı inildikçe metalik karakter artar; polonyum metalik iletkenlik gösteren radyoaktif bir elementtir.'),
  ('Polonyum-210\'un statik elektriği gidermek için kullanılan fırçalarda bulunmasının nedeni hangisidir?', 'Yaydığı alfa taneciklerinin havayı iyonlaştırıp yükü boşaltması', ['Fırçayı mıknatıslaması', 'Toz taneciklerini eritmesi', 'Görünür ışık yayarak tozları göstermesi ve temizliği kolaylaştırması'], 'Alfa tanecikleri havada iyonlar oluşturur; bu iyonlar yüzeydeki statik yükü nötrleştirir.'),
  ('Kalkojenlerin hidrojenle oluşturduğu H₂O, H₂S, H₂Se ve H₂Te bileşiklerinde X–H bağ enerjisi nasıl değişir?', 'Oksijenden tellüre doğru azalır', ['Oksijenden tellüre doğru artar', 'Dördünde de eşittir', 'Önce azalır, sonra çok büyük bir sıçramayla artar'], 'Merkez atom büyüdükçe orbital örtüşmesi zayıflar ve bağ uzar; bu nedenle H₂Te en kolay ayrışan hidrürdür.'),
  ('Flor gazını ilk kez 1886\'da elektrolizle elde edip bu başarısıyla 1906 Nobel Kimya Ödülü\'nü alan kimyacı kimdir?', 'Henri Moissan', ['Antoine Henri Becquerel', 'Louis Pasteur', 'Joseph Louis Gay-Lussac'], 'Moissan, susuz HF içinde çözülmüş KHF₂\'yi soğutulmuş platin düzenekte elektroliz ederek flor elde etti.'),
  ('Florun serbest element olarak elde edilmesinin klorunkinden çok daha geç (yaklaşık 70 yıl sonra) gerçekleşmesinin nedeni hangisidir?', 'Aşırı etkin olduğu için oluştuğu anda düzenekle ve çevreyle tepkimeye girmesi', ['Doğada hiç bileşiğinin bulunmaması', 'Radyoaktif olup hemen bozunması', 'Elektriği çok iyi iletip elektrotları kısa devre yaptırması ve düzeneği yakması'], 'Flor en güçlü yükseltgendir; camı, metalleri ve suyu bile saldırır. Bu yüzden onu ayırmaya çalışan birçok kimyacı yaralanmıştır.'),
  ('Soluk sarı flordan mor-siyah iyoda kadar halojen elementlerinin renkleri grupta aşağı doğru nasıl bir eğilim gösterir?', 'Giderek koyulaşır', ['Giderek açılır ve iyot renksiz olur', 'Dördünde de aynı ton görülür', 'Önce koyulaşır, sonra brom ve iyotta tamamen renksizleşir'], 'F₂ soluk sarı, Cl₂ sarımsı yeşil, Br₂ kırmızı-kahverengi, I₂ koyu mor-siyahtır; büyük moleküller daha uzun dalga boylu ışığı soğurur.'),
  ('Klor gazını 1774\'te ilk kez elde eden, ancak onu bir element olarak tanımayan İsveçli kimyacı kimdir?', 'Carl Wilhelm Scheele', ['Henri Moissan', 'Sir Humphry Davy', 'John Dalton'], 'Scheele kloru hidroklorik asidi mangan dioksitle ısıtarak elde etti; elementel doğasını 1810\'da Humphry Davy gösterdi.'),
  ('Klor gazının Birinci Dünya Savaşı\'nda 1915\'te Ypres\'te kimyasal silah olarak kullanılması gazın hangi özelliğinden yararlanılarak gerçekleştirilmiştir?', 'Havadan yoğun olduğu için siperlere çökmesi', ['Havadan çok hafif olup yükselmesi', 'Kokusuz ve renksiz olup fark edilmemesi', 'Patlayıcı olup siperleri yıkması ve büyük yangınlar çıkarması'], 'Klor havadan yaklaşık 2,5 kat yoğundur; yere yakın kalarak çukur ve siperlere dolar ve solunum yollarına ağır zarar verir.'),
  ('Klorun yükseltgenme basamağı NaCl\'de −1 iken KClO₄\'te kaçtır?', '+7', ['+5', '+3', '+1'], 'K = +1, dört O toplam −8 olduğundan Cl = +7\'dir. Klor 7 değerlik elektronunun hepsini bağa verebilir.'),
  ('Doğal olarak oluşan elementler arasında yer kabuğunda en az bulunanlardan biri olan, tüm izotopları radyoaktif halojen hangisidir?', 'Astatin', ['İyot', 'Brom', 'Tennesin'], 'Astatin yalnızca uranyum ve toryumun bozunma zincirlerinde kısa ömürlü olarak oluşur; yer kabuğundaki toplam miktarı bir gramın altında tahmin edilir.'),
  ('Astatin adı Yunanca hangi anlamdaki sözcükten türetilmiştir?', 'Kararsız', ['Yıldız', 'Mor', 'Ağır metal'], 'Tüm izotopları kısa yarı ömürlü olduğu için Yunanca \'astatos\' (kararsız) sözcüğünden adlandırıldı.'),
  ('Halojenlerin yükseltgen gücü flordan iyoda doğru azalır. Bu eğilimin temel nedeni hangisidir?', 'Atom büyüdükçe gelen elektronun çekirdekçe daha zayıf çekilmesi', ['Grupta aşağı inildikçe değerlik elektron sayısının azalması', 'İyotun bir metal olması', 'Florun en büyük atom yarıçapına sahip olması ve elektronları uzaktan çekmesi'], 'Küçük flor atomu elektron kazanmaya çok isteklidir; iyot gibi büyük atomlarda değerlik katmanı çekirdekten uzaktır.'),
  ('Bromlu bileşiklerin plastik ve tekstil ürünlerine katılmasının yaygın bir amacı hangisidir?', 'Alev geciktirici olarak yanmayı yavaşlatmak', ['Ürünü mıknatıslanabilir yapmak', 'Ürünün suda çözünmesini sağlamak', 'Ürünü radyoaktif işaretleyip izlenebilir kılmak'], 'Bromlu alev geciktiriciler yanma sırasında zincir tepkimelerini kesen radikaller oluşturur; bazıları çevresel kalıcılıkları nedeniyle sınırlandırılmıştır.'),
  ('Halojenlerin elektronegatiflikleri (Pauling ölçeği) F 4,0; Cl 3,2; Br 3,0; I 2,7 civarındadır. Bu verilere göre hangi iki halojen arasındaki bağ en polardır?', 'I–F', ['Cl–F', 'Br–Cl', 'I–Br'], 'Polarlık elektronegatiflik farkıyla artar: I–F için fark yaklaşık 1,3 ile en büyüktür.'),
  ('Atmosferdeki argonun büyük kısmının kaynağı hangi süreçtir?', 'Kayaçlardaki potasyum-40\'ın bozunması', ['Güneş rüzgârıyla gelen argon iyonları', 'Okyanuslardaki tuzun buharlaşması', 'Bitkilerin fotosentez sırasında ürettiği argon gazı'], 'K-40\'ın bir kısmı elektron yakalamayla Ar-40\'a dönüşür; jeolojik zaman boyunca biriken bu argon atmosfere geçmiştir.'),
  ('Neon, kripton ve ksenon adlarının Yunanca anlamları sırasıyla hangisidir?', 'Yeni, gizli, yabancı', ['Gizli, yeni, yabancı', 'Yabancı, yeni, gizli', 'Parlak, ağır, soğuk ve tembel'], 'Ramsay ve Travers 1898\'de sıvı havanın damıtılmasıyla buldukları gazlara neos (yeni), kryptos (gizli) ve ksenos (yabancı) adlarını verdi.'),
  ('Titanyumun başlıca cevherlerinden biri olan ilmenitin formülü hangisidir?', 'FeTiO₃', ['TiCl₄', 'CaTiSiO₅', 'Ti₃(PO₄)₄'], 'İlmenit demir titanyum oksittir; rutil (TiO₂) ile birlikte titanyumun en önemli kaynaklarındandır.'),
  ('Kromun +3 ve +6 yükseltgenme basamaklarındaki bileşikleri için hangisi doğrudur?', 'Cr(VI) türleri güçlü yükseltgen ve kanserojendir; Cr(III) daha kararlı ve çok daha az zehirlidir', ['İki basamaktaki bileşikler de tamamen zararsızdır', 'Cr(III) bileşikleri patlayıcıdır; Cr(VI) bileşikleri ise gıdalarda katkı maddesi olarak serbestçe kullanılır', 'Krom bu iki basamağı hiç almaz'], 'Dikromat ve kromat gibi Cr(VI) türleri hücrelere girip hasar verir; Cr(III) daha az hareketli ve daha az zehirlidir.'),
  ('Çelik üretiminde manganın eklenmesinin bir başlıca işlevi hangisidir?', 'Kükürt ve oksijeni bağlayarak çeliğin kırılganlığını azaltmak', ['Çeliği oda sıcaklığında sıvılaştırmak', 'Çeliğin elektrik iletkenliğini sıfırlamak', 'Çeliği tümüyle paslanmaz ve manyetik olmayan bir metale dönüştürmek'], 'Mangan, kükürdü MnS olarak bağlayıp sıcakta kırılganlığı önler ve oksijen gidericidir; ayrıca çeliği sertleştirir.'),
  ('Birinci sıra geçiş metallerinin en yüksek yükseltgenme basamakları skandiyumdan (+3) mangana (+7) doğru artar. Bu artışın nedeni hangisidir?', 'Bağa katılabilen 4s ve 3d elektronlarının sayısının artması', ['Atom yarıçapının hızla büyümesi', 'Bu metallerin elektronegatifliğinin flordan büyük olması', 'Çekirdekteki nötron sayısının azalması ve çekirdeğin giderek kararsızlaşması'], 'Sc\'de 3, Ti\'de 4, V\'de 5, Cr\'de 6, Mn\'de 7 değerlik elektronu vardır; en yüksek basamak bu sayıya eşittir.'),
  ('Dünya\'nın tamamı (çekirdek dâhil) düşünüldüğünde kütlece en bol bulunan element hangisidir?', 'Demir', ['Oksijen', 'Silisyum', 'Alüminyum'], 'Yer kabuğunda oksijen en boldur; ancak çekirdeğin büyük ölçüde demir-nikel olması nedeniyle gezegenin tamamında demir kütlece birinci sıradadır.'),
  ('Bir demir mıknatıs yaklaşık 770 °C\'nin üzerine ısıtıldığında mıknatıslığını kaybeder. Bu sıcaklığa ne ad verilir?', 'Curie sıcaklığı', ['Kritik sıcaklık', 'Üçlü nokta sıcaklığı', 'Kelvin sıcaklığı'], 'Curie sıcaklığının üzerinde ısıl hareket spinlerin düzenli dizilimini bozar ve ferromanyetiklik kaybolur.'),
  ('Doğada bulunan ve doğal mıknatıs özelliği gösteren demir cevheri manyetitin formülü hangisidir?', 'Fe₃O₄', ['Fe₂O₃', 'FeS₂', 'FeCO₃'], 'Manyetit hem Fe²⁺ hem Fe³⁺ içeren karışık bir oksittir; pusulanın keşfinde kullanılan \'mıknatıs taşı\' da manyetittir.'),
  ('Kobalt adı, Alman madencilerin cevherden beklenen metali alamayınca suçladıkları hangi varlıktan gelir?', 'Kobold adı verilen kötü huylu bir cin', ['Bir Yunan deniz tanrısı', 'Bir İsveç köyü', 'Mavi renkli bir dağ çiçeği ve onun kökü'], 'Kobalt cevherleri arsenik içerdiğinden kavrulunca zehirli dumanlar çıkarıyordu; madenciler bunu dağ cinlerine (kobold) bağladı.'),
  ('Nikelin, karbon monoksitle uçucu Ni(CO)₄ oluşturup yeniden ayrıştırılması esasına dayanan saflaştırma yöntemi hangisidir?', 'Mond yöntemi', ['Hall-Héroult yöntemi', 'Kroll yöntemi', 'Bessemer yöntemi'], 'Ni(CO)₄ yaklaşık 50 °C\'de oluşur, yaklaşık 200 °C\'de ayrışarak çok saf nikel verir; safsızlıklar karbonil oluşturmaz.'),
  ('Altını ve platini çözebilen \'kral suyu\' hangi karışımdır?', 'Derişik nitrik asit ile derişik hidroklorik asidin karışımı', ['Derişik sülfürik asit ile suyun karışımı', 'Sodyum hidroksit ile amonyağın karışımı', 'Hidrojen peroksit ile sirkenin karışımı ve az miktarda sodyum klorür eklenmiş çözeltisi'], 'Nitrik asit altını yükseltgerken klorür iyonları Au³⁺\'yı kararlı AuCl₄⁻ kompleksi olarak bağlar; tek başına iki asit de altını çözemez.'),
  ('Bakır, gümüş ve altının \'madeni para metalleri\' olarak tarih boyunca kullanılmasını sağlayan ortak özellik hangisidir?', 'Görece az etkin olup korozyona dayanıklı ve kolay işlenebilir olmaları', ['Üçünün de oda sıcaklığında sıvı olması', 'Üçünün de mıknatısa çekilmesi', 'Yer kabuğunda en bol bulunan metaller olmaları ve her yerde kolayca bulunmaları'], '11. grup metalleri soy metal özelliği gösterir; doğada saf hâlde de bulunabilir ve uzun süre bozulmazlar.'),
  ('Çinkonun bağışıklık sistemi ve yara iyileşmesi için önemli olmasının temel nedeni hangisidir?', 'Yüzlerce enzimin yapısında ya da işleyişinde görev alması', ['Kanda oksijen taşıması', 'Kemiklerin ana minerali olması', 'Sinir hücrelerinde elektrik akımını tek başına iletmesi ve kasları kasması'], 'Çinko, karbonik anhidraz gibi birçok enzimin aktif bölgesinde bulunur; eksikliği bağışıklığı ve büyümeyi bozar.'),
  ('Bakır ve pirinç kapı kollarının bakteri sayısını azaltmasının temel nedeni hangisidir?', 'Yüzeyden çözünen bakır iyonlarının mikroorganizmalara zarar vermesi', ['Yüzeyin sürekli ısınması', 'Bakırın ışık yayması', 'Bakır yüzeyin bakterileri mıknatısla çekip tutması ve uzaklaştırması'], 'Bakır iyonları hücre zarlarına ve enzimlere zarar verir; bu \'oligodinamik etki\' bakır yüzeylerin hijyen amaçlı kullanılmasına yol açmıştır.'),
  ('Osmiyum elementinin adı Yunanca \'koku\' anlamına gelen sözcükten türetilmiştir. Bu adın nedeni hangisidir?', 'Uçucu ve keskin kokulu osmiyum tetroksit oluşturması', ['Metalinin güzel bir çiçek kokusu yayması', 'Burun ilaçlarında kullanılması', 'Kokusuz olduğu için ironik biçimde adlandırılması ve bu adın tanınması'], 'OsO₄ oda sıcaklığında kolayca buharlaşan, çok zehirli ve keskin kokulu bir bileşiktir.'),
  ('Dinozorların yok oluşuna ilişkin göktaşı çarpması kuramını destekleyen önemli kanıt, dünyanın birçok yerinde aynı yaştaki kayaç katmanında hangi elementin olağandışı yüksek derişimde bulunmasıdır?', 'İridyum', ['Kurşun', 'Alüminyum', 'Uranyum'], 'Alvarez ve arkadaşları 1980\'de Kretase-Paleojen sınırındaki ince kil katmanında, yer kabuğunda çok az ama göktaşlarında daha bol bulunan iridyum zenginleşmesi buldu.'),
  ('2019\'a kadar kilogramın tanımı olan uluslararası prototip kilogram hangi alaşımdan yapılmıştı?', 'Platin-iridyum', ['Demir-nikel', 'Bakır-kalay', 'Altın-gümüş-bakır'], 'Paris yakınlarında saklanan silindir %90 platin ve %10 iridyumdan yapılmıştı; bu alaşım çok yoğun, sert ve korozyona dayanıklıdır.'),
  ('Molibden disülfürün (MoS₂) katı yağlayıcı olarak kullanılması hangi yapısal özelliğine dayanır?', 'Grafite benzer biçimde birbiri üzerinde kayan katmanlardan oluşması', ['Oda sıcaklığında sıvı olması', 'Çok yüksek yoğunluklu bir metal olması', 'Suyla temas edince bol köpük oluşturması ve yüzeyleri kayganlaştıran bir sabuna dönüşmesi'], 'MoS₂ katmanları arasında zayıf etkileşimler bulunur; katmanlar kolayca kayarak sürtünmeyi azaltır.'),
  ('Cıvanın simgesi Hg, Latince hydrargyrum sözcüğünden gelir. Bu sözcüğün anlamı hangisidir?', 'Sıvı gümüş', ['Ağır taş', 'Parlak ateş', 'Gezgin yıldız ve gökyüzü'], 'Hydrargyrum Yunanca \'su\' ve \'gümüş\' sözcüklerinden oluşur; cıvanın gümüş gibi parlak bir sıvı olmasını anlatır.'),
  ('Ressamların kullandığı parlak sarı ve turuncu \'kadmiyum\' boyalarının pigmenti hangi bileşiktir?', 'Kadmiyum sülfür', ['Kadmiyum klorür', 'Kadmiyum hidroksit', 'Kadmiyum karbonat'], 'CdS sarı, kadmiyum sülfoselenür turuncu-kırmızı tonlar verir; zehirlilikleri nedeniyle kullanımları sınırlandırılmıştır.'),
  ('Ağır metallerin (örneğin cıva, kurşun, kadmiyum) besin zincirinde üst basamaklara doğru giderek daha yüksek derişimde bulunmasına ne ad verilir?', 'Biyolojik birikim ve büyüme', ['Ötrofikasyon', 'Fotosentez', 'Denitrifikasyon'], 'Bu metaller vücuttan zor atıldığı için her besin basamağında birikir; yırtıcı balıklarda cıva düzeyinin yüksek olmasının nedeni budur.'),
  ('\'Nadir toprak elementleri\' adı için hangisi doğrudur?', 'Çoğu yer kabuğunda pek az değildir; ad, zor ayrılmalarından ve tarihsel kökenden gelir', ['Grubun tüm üyeleri yer kabuğunda altından çok daha az bulunur ve yalnız göktaşlarında çıkarılır', 'Bu elementler yalnız Ay\'da bulunur', 'Ad, bu elementlerin radyoaktif olmasından gelir'], 'Örneğin seryum yer kabuğunda bakır kadar boldur; ancak birbirine çok benzeyen bu elementler cevherde karışık hâlde bulunur ve zor ayrılır.'),
  ('Çakmak taşlarında kıvılcım çıkarmak için kullanılan demir alaşımının temel bileşeni olan, lantanitlerin en bolu sayılan element hangisidir?', 'Seryum', ['Gadolinyum', 'Neodimyum', 'Lutesyum'], 'Seryumca zengin karışık metal (mischmetal) demirle alaşımlanır; sürtünmeyle kopan küçük parçacıklar havada tutuşup kıvılcım oluşturur.'),
  ('Lantanitler arasında hiçbir kararlı izotopu bulunmayan tek element hangisidir?', 'Prometyum', ['Lantan', 'Seryum', 'Lutesyum'], 'Prometyumun (Z = 61) bütün izotopları radyoaktiftir; doğada uranyum cevherlerinde yok denecek kadar az bulunur.'),
  ('Lantanitlerin birbirinden ayrılması neden çok zordur?', 'Neredeyse tümü +3 iyonu oluşturur ve iyon yarıçapları birbirine çok yakındır', ['Lantanitlerin tamamı oda koşullarında gaz hâlindedir', 'Lantanitler bileşik oluşturmaz', 'Bu elementler suda çözünmeyen metallerdir ve bilinen bütün çözücülere karşı dirençlidir'], 'Kimyasal benzerlik nedeniyle ayırma, iyon değiştirme ve çözücü özütlemesi gibi yöntemlerin çok kez tekrarlanmasını gerektirir.'),
  ('Uranyumdan sonra gelen ilk element olan ve 1940\'ta McMillan ile Abelson tarafından elde edilen element hangisidir?', 'Neptünyum', ['Plütonyum', 'Amerikyum', 'Küriyum'], 'Neptünyum (Z = 93), uranyumun nötronla bombardımanı sonucu oluşan U-239\'un beta bozunmasıyla elde edildi ve Neptün gezegeninin adını aldı.'),
  ('Voyager ve Cassini gibi uzak gezegenlere giden uzay araçlarında elektrik üretmek için kullanılan, bozunma ısısı yayan izotop hangisidir?', 'Plütonyum-238', ['Uranyum-235', 'Karbon-14', 'Kobalt-60 ve sezyum-137'], 'Pu-238 yaklaşık 88 yıl yarı ömürle alfa bozunması yapar; açığa çıkan ısı radyoizotop termoelektrik jeneratörlerde elektriğe çevrilir.'),
  ('Uranyumu 1789\'da ilk kez tanımlayan ve adını sekiz yıl önce keşfedilen gezegenden alarak koyan Alman kimyacı kimdir?', 'Martin Heinrich Klaproth', ['Dmitri Mendeleyev', 'Ernest Rutherford', 'Wilhelm Conrad Röntgen ve Pierre Curie'], 'Klaproth uranyumu uraninit (pitchblende) mineralinde bir oksit olarak tanımladı; Uranüs 1781\'de keşfedilmişti.'),
  ('IUPAC\'ın henüz adı konmamış elementler için kullandığı geçici sistematik adlandırmada \'un\' 1, \'bi\' 2, \'nil\' 0 ve \'enn\' 9 rakamını gösterir. Buna göre \'unbinilyum\' kaç numaralı elementi belirtir?', '120', ['112', '102', '129'], 'Rakam kökleri sırayla okunur: un (1) + bi (2) + nil (0) → 120.'),
  ('Geçici adı \'ununtriyum\' olan ve 2016\'da kalıcı adını alan 113 numaralı element hangisidir?', 'Nihonyum', ['Moskovyum', 'Tennesin', 'Kopernikyum'], 'Nihonyum (Nh) Japonya\'daki RIKEN\'de üretildi ve Asya\'da keşfedilen ilk element olarak Japonya\'nın adını aldı.'),
  ('Nükleer fizikte \'kararlılık adası\' kavramı neyi öngörür?', 'Belirli proton ve nötron sayılarında süper ağır çekirdeklerin görece uzun ömürlü olabileceğini', ['Bütün ağır elementlerin sonsuza dek kararlı olduğunu', 'Bir okyanus adasında yeni elementlerin bulunacağını', 'Elementlerin yalnızca volkanik adalarda bulunan özel minerallerde oluştuğunu ve başka yerde bulunamayacağını'], 'Kapalı kabuk (sihirli sayı) etkisiyle bazı süper ağır izotopların, komşularından çok daha uzun yarı ömürlü olması beklenmektedir.'),
  ('Elementleri bugünkü gibi Latince adlarının bir ya da iki harfiyle gösteren simge sistemini 1813-14 yıllarında öneren kimyacı kimdir?', 'Jöns Jacob Berzelius', ['John Dalton', 'Dmitri Mendeleyev', 'Antoine Lavoisier'], 'Dalton elementleri içi farklı işaretli dairelerle gösteriyordu; Berzelius\'un harf sistemi daha pratik olduğu için benimsendi.'),
  ('Aşağıdaki elementlerden hangisinin simgesi, Türkçe adından değil, Latince kökenli farklı bir addan gelir?', 'Kalay', ['Alüminyum', 'Nikel', 'Argon'], 'Kalayın simgesi Latince stannum\'dan gelen Sn\'dir; alüminyum Al, nikel Ni, argon Ar simgeleri Türkçe adlarıyla da uyumludur.'),
  ('Tantal ve niyobyum adları Yunan mitolojisinde baba-kız olan iki figürden gelir. Bu adlandırma iki element arasındaki hangi ilişkiyi yansıtır?', 'Kimyasal özelliklerinin birbirine çok benzemesi ve doğada birlikte bulunmaları', ['Birinin diğerinin radyoaktif bozunma ürünü olması', 'İkisinin de oda sıcaklığında sıvı olması', 'İkisinin de aynı yıl ve aynı ülkede keşfedilmiş olmaları ve aynı bilim insanına ait olmaları'], 'Niobe, Tantalos\'un kızıdır; niyobyum ve tantal aynı gruptadır, birlikte bulunur ve zor ayrılır.'),
  ('İskoçya\'daki bir köyün kurşun madenlerinde bulunan mineralden adını alan element hangisidir?', 'Stronsiyum', ['Skandiyum', 'Berkelyum', 'Hafniyum'], 'Stronsiyum adını Strontian köyünden alır; mineral stronsiyanit orada bulunmuştur.'),
  ('Hafniyum ve lutesyum adlarının ortak noktası hangisidir?', 'İkisi de bir başkentin Latince adından türetilmiştir', ['İkisi de bir gezegenin adını taşır', 'İkisi de bir bilim insanının soyadıdır', 'İkisi de bir tanrının adından gelir ve mitolojiye dayanır'], 'Hafnia Kopenhag\'ın, Lutetia Paris\'in Latince adıdır.'),
  ('Magnezyum ve manganın adları aynı kökten, Yunanistan\'ın hangi bölgesinden gelir?', 'Magnesia', ['Atina', 'Makedonya', 'Girit'], 'Magnesia bölgesindeki mineraller hem magnezyum hem mangan içeren cevherlere ad vermiştir; \'mıknatıs\' (magnet) sözcüğü de aynı kökenlidir.'),
  ('Rodyum elementinin adı Yunanca \'gül\' anlamına gelen sözcükten türetilmiştir. Bu ad hangi gözleme dayanır?', 'Tuzlarının gül rengi (pembe-kırmızı) olması', ['Gül yağının içinde bulunması', 'Gül bahçelerinde keşfedilmesi', 'Metalinin gül gibi koku yayması ve parfümde kullanılması'], 'Wollaston 1803\'te platin cevherinden ayırdığı bu elementin tuzlarının pembe-kırmızı renkte olduğunu gözledi.'),
  ('Albert Einstein ve Enrico Fermi\'nin adlarını taşıyan iki elementin atom numaraları sırasıyla hangisidir?', '99 ve 100', ['101 ve 102', '97 ve 98', '104 ve 105'], 'Aynştaynyum (Es) 99, fermiyum (Fm) 100 numaralı elementtir.'),
  ('Metalik yarıçap nasıl tanımlanır?', 'Metal kristalinde komşu iki atomun çekirdekleri arasındaki uzaklığın yarısı', ['Metal atomunun en dıştaki elektronunun çekirdeğe olan uzaklığının iki katı alınarak bulunan değer', 'Metal iyonunun suda kapladığı hacim', 'Metal kristalinin birim hücre kenarının tamamı'], 'Atomun kesin bir sınırı olmadığı için yarıçap, deneysel olarak ölçülebilen çekirdekler arası uzaklıktan türetilir.'),
  ('Atom numarası arttıkça atom yarıçapında en büyük ani artış hangi geçişte görülür?', 'Bir soy gazdan sonraki alkali metale geçerken', ['Bir alkali metalden toprak alkali metale geçerken', 'Bir halojenden soy gaza geçerken', 'Bir geçiş metalinden komşu geçiş metaline geçerken'], 'Alkali metalde yeni bir katman açılır; örneğin neon yaklaşık 38 pm (kovalent tahmin) iken sodyum yaklaşık 186 pm metalik yarıçapa sahiptir.'),
  ('Birinci sıra geçiş metallerinde (Sc\'den Zn\'ye) atom yarıçapının ana grup elementlerine göre çok az değişmesinin nedeni hangisidir?', 'Eklenen elektronların iç katmandaki 3d orbitallerine girerek dış elektronları perdelemesi', ['Bu metallerin proton sayısının değişmemesi', 'Eklenen elektronların her adımda yeni bir dış katman açması ve önceki katmanı boşaltması', 'Geçiş metallerinin hiç değerlik elektronu bulunmaması'], 'Artan çekirdek yükü, içteki d elektronlarının perdelemesiyle büyük ölçüde dengelenir; dış 4s elektronlarının hissettiği etkin yük az değişir.'),
  ('Bir öğrenci \'periyotta sağa gidildikçe elektron sayısı arttığına göre atom büyümelidir\' diyor. Bu düşünceyi düzelten en doğru açıklama hangisidir?', 'Elektronlar aynı katmana girerken artan proton sayısı katmanı çekirdeğe daha çok yaklaştırır', ['Elektronların kütlesi atomu küçültür', 'Sağa gidildikçe katman sayısı azalır', 'Elektronlar eklendikçe nötronlar atomdan ayrılır, bu da hacmin ve kütlenin birlikte küçülmesine yol açar'], 'Aynı katmandaki elektronlar birbirini zayıf perdeler; etkin çekirdek yükü artar ve atom büzülür.'),
  ('Bir metal atomu katyon oluşturduğunda yarıçapın belirgin biçimde küçülmesinin en önemli nedeni çoğu zaman hangisidir?', 'En dış katmanın tümüyle boşalması', ['Çekirdekteki proton sayısının azalması', 'Atomun nötron kaybetmesi', 'Kalan elektronların çekirdekten uzaklaşması'], 'Örneğin Na → Na⁺ dönüşümünde 3s elektronu gider ve iyon bir katman eksik kalır; ayrıca elektron başına düşen çekirdek çekimi artar.'),
  ('Mg²⁺ ve Ca²⁺ iyonlarından hangisinin yük yoğunluğu (yük/yarıçap oranı) daha büyüktür ve bunun bir sonucu nedir?', 'Mg²⁺; su moleküllerini daha güçlü çekerek daha büyük hidratasyon enerjisi verir', ['Ca²⁺; daha küçük olduğu için', 'İkisi eşittir; çünkü yükleri aynıdır', 'Mg²⁺; ancak hiç hidratlaşmaz, su moleküllerini iter ve bu nedenle suda çözünmez'], 'Aynı yükte daha küçük olan Mg²⁺\'nın yük yoğunluğu büyüktür; bu nedenle hidratasyon enerjisi Ca²⁺\'nınkinden daha eksidir.'),
  ('Soy gazların atom yarıçapı karşılaştırmalarında çoğunlukla kovalent yarıçap yerine van der Waals yarıçapı verilmesinin nedeni hangisidir?', 'Soy gaz atomlarının çoğunun birbirleriyle kararlı kovalent bağ kurmaması', ['Soy gazların çekirdeğinin olmaması', 'Soy gazların yalnız iyon olarak bulunması', 'Van der Waals yarıçapının her zaman ve her element için kovalent yarıçapa tam olarak eşit olması'], 'Kovalent yarıçap bağlı atomlardan ölçülür; tek atomlu soy gazlarda yalnızca bağsız atomların temas uzaklığı ölçülebilir.'),
  ('Aynı element için iyonların yarıçapı Mn²⁺ > Mn⁴⁺ > Mn⁷⁺ sırasıyla küçülür. Bu sıralamayı açıklayan genel ilke hangisidir?', 'Aynı çekirdek etrafında elektron sayısı azaldıkça kalan elektronların daha sıkı çekilmesi', ['Yük arttıkça çekirdekteki proton sayısının da artması', 'Yüksek yüklü iyonlarda yeni katmanların açılması ve elektronların dışarı taşınması', 'İyonların yarıçapının yükten bağımsız olması'], 'Çekirdek yükü sabitken elektron eksildikçe elektron-elektron itmesi azalır ve bulut büzülür.'),
  ('Na⁺ ve Ca²⁺ iyonlarının yarıçapları birbirine çok yakındır (her ikisi de yaklaşık 100 pm). Bu benzerliğin doğadaki bir sonucu hangisidir?', 'Bazı minerallerde birbirlerinin yerine geçebilmeleri', ['İkisinin de suyla tepkimeye girmemesi', 'İkisinin de aleve aynı rengi vermesi', 'Aynı elementin iki farklı izotopu olmaları ve bu nedenle aynı kristal yapıyı paylaşmaları'], 'Benzer büyüklükteki iyonlar kristal örgüde yer değiştirebilir; plajiyoklaz feldspatlarında Na ile Ca\'nın birbirinin yerine geçmesi buna örnektir.'),
  ('Hafniyumun (Z = 72) atom yarıçapı (159 pm) üstündeki zirkonyumunkiyle (160 pm) neredeyse aynıdır. Bu benzerliğin kimyasal bir sonucu hangisidir?', 'İki elementin birbirinden ayrılmasının çok zor olması', ['Hafniyumun bir soy gaz olması', 'Zirkonyumun radyoaktif olması', 'Hafniyumun suda kolayca çözünüp zirkonyumun hiçbir çözücüde çözünmemesi'], 'Benzer büyüklük ve aynı değerlik elektron dizilimi nedeniyle Zr ve Hf doğada birlikte bulunur; hafniyum 1923\'e kadar fark edilmemişti.'),
  ('İyonlaşma enerjisi tanımlanırken elektronun \'gaz hâlindeki\' atomdan koparıldığı belirtilir. Bu koşulun amacı hangisidir?', 'Komşu atomlarla etkileşimlerin ölçülen değeri değiştirmesini önlemek', ['Atomun daha hızlı hareket etmesini sağlamak', 'Elektronun ışık yaymasını engellemek', 'Ölçümün yalnız oda sıcaklığında ve açık havada, kapsız yapılabilmesini sağlamak'], 'Katı ya da sıvıda atomlar birbirine bağlıdır; yalnız yalıtılmış atom için ölçülen enerji elementin kendine özgü değerini verir.'),
  ('Hidrojen atomunun birinci iyonlaşma enerjisi yaklaşık kaç kJ/mol\'dür?', '1312', ['496', '2372', '738'], 'Hidrojenin iyonlaşma enerjisi 13,6 eV ya da yaklaşık 1312 kJ/mol\'dür; 496 sodyumun, 2372 helyumun, 738 magnezyumun değeridir.'),
  ('Kararlı elementler arasında birinci iyonlaşma enerjisi en düşük olan sezyumun ışığa duyarlı fotosellerde kullanılmasının nedeni hangisidir?', 'Düşük enerjili ışığın bile yüzeyinden elektron koparabilmesi', ['Işığı tümüyle yansıtması', 'Karanlıkta kendiliğinden elektrik üretmesi', 'Radyoaktif olup sürekli elektron saçması ve bu sayede pil gibi çalışması'], 'Sezyumun değerlik elektronu çok gevşek tutulduğu için görünür ışık fotoelektrik olaya yol açabilir.'),
  ('Bir X elementinin ilk beş iyonlaşma enerjisi (kJ/mol) 1086, 2353, 4620, 6223 ve 37 830\'dur. Bu verilerden çıkarılabilecek en doğru sonuç hangisidir?', 'X\'in dört değerlik elektronu vardır', ['X\'in iki değerlik elektronu vardır', 'X bir soy gazdır', 'X\'in beş değerlik elektronu vardır ve bir alkali metaldir'], 'Dördüncü ile beşinci değer arasındaki büyük sıçrama, beşinci elektronun iç katmandan koparıldığını gösterir; bu değerler karbona aittir.'),
  ('Elektron ilgisi değerleri genellikle ekzotermik süreçler için eksi işaretle verilir. Klorun elektron ilgisinin yaklaşık −349 kJ/mol olması ne anlama gelir?', '1 mol gaz klor atomu elektron kazanınca 349 kJ enerji açığa çıkar', ['1 mol klor atomundan elektron koparmak 349 kJ gerektirir', 'Klor elektron kazanırken 349 kJ enerji soğurur', '1 mol klor molekülünü atomlarına ayırmak için tam olarak 349 kJ enerji gerekir'], 'Eksi işaret, Cl(g) + e⁻ → Cl⁻(g) sürecinin enerji verdiğini gösterir.'),
  ('Berilyum ve magnezyumun elektron ilgisinin sıfıra yakın ya da elverişsiz (enerji gerektiren) olmasının nedeni hangisidir?', 'Gelen elektronun dolu ns² alt katmanının üstündeki daha yüksek enerjili np orbitaline girmesi', ['Bu elementlerin hiç değerlik elektronu bulunmaması', 'Bu atomların çekirdek yükünün sıfır olması', 'Elektronun çekirdeğe doğrudan düşüp bir protonu nötrleştirmesi ve atomun bir nötron kazanması'], 'Dolu s alt katmanı ek kararlılık sağlar; gelen elektron daha az çekilen p orbitaline yerleşmek zorundadır.'),
  ('Elektron ilgisi ile elektronegatiflik arasındaki temel fark hangisidir?', 'Elektron ilgisi yalıtılmış atomun enerji değişimidir; elektronegatiflik bağlı atomun göreli çekimidir', ['İkisi aynı kavramın farklı adlarıdır', 'Elektronegatiflik kJ/mol ile ölçülen ve kalorimetreyle doğrudan belirlenen bir enerji değeridir', 'Elektron ilgisi yalnızca metaller için tanımlıdır'], 'Elektron ilgisi deneysel bir enerji değeridir; elektronegatiflik ise bağlı atomlar için tanımlanan birimsiz, göreli bir ölçektir.'),
  ('Bir öğrenci \'iyonlaşma enerjisi yüksek olan atomun elektron ilgisi de her zaman yüksektir\' diyor. Bu genellemeye karşı en güçlü örnek hangisidir?', 'Soy gazların iyonlaşma enerjisi çok yüksek olduğu hâlde elektron kazanmaya isteksiz olması', ['Florun hem iyonlaşma enerjisinin hem elektron ilgisinin yüksek olması', 'Sodyumun iki değerinin de düşük olması', 'Klorun elektron ilgisinin yüksek olması ve iyonlaşma enerjisinin de görece yüksek bulunması'], 'Soy gazlarda elektron koparmak zordur ama eklenen elektron yeni bir katmana gireceğinden elektron ilgisi elverişsizdir.'),
  ('Mulliken\'in elektronegatiflik tanımı hangi iki niceliğe dayanır?', 'İyonlaşma enerjisi ile elektron ilgisinin ortalamasına', ['Atom kütlesi ile yoğunluğun çarpımına', 'Erime noktası ile kaynama noktasının farkına', 'Atom yarıçapı ile nötron sayısının oranına ve izotop bolluklarına'], 'Mulliken, bir atomun hem elektronu tutma (iyonlaşma enerjisi) hem de elektron çekme (elektron ilgisi) eğilimini birlikte değerlendirdi.'),
  ('Elektronegatifliğin bir birimi olmamasının ve doğrudan ölçülememesinin nedeni hangisidir?', 'Bağ enerjileri gibi ölçülebilir niceliklerden türetilen göreli bir ölçek olması', ['Yalnızca radyoaktif elementler için tanımlanması', 'Elektronegatifliğin gram ya da kilogram gibi bir kütle birimiyle ifade edilmesi gereken bir nicelik olması', 'Atomların hiçbir zaman bağ yapmaması'], 'Pauling ölçeği, bağ enerjilerinden yararlanarak elementleri birbirine göre sıralar; florun değeri yaklaşık 4 kabul edilir.'),
  ('Hidrojenin Pauling elektronegatifliği (2,20) en yakın olarak hangi elementinkine benzer?', 'Karbon (2,55) ve fosfor (2,19)', ['Flor (3,98)', 'Sodyum (0,93)', 'Oksijen (3,44) ve kükürt (2,58)'], 'Bu benzerlik C–H bağlarının neredeyse apolar olmasının ve hidrokarbonların sudan farklı davranmasının nedenlerinden biridir.'),
  ('Bir öğrenci \'periyotta soldan sağa gidildikçe metalik karakter azalır\' bilgisini kullanmak istiyor. 3. periyotta hangi üç element sırasıyla metal, yarı metal ve ametaldir?', 'Alüminyum, silisyum, fosfor', ['Sodyum, magnezyum, alüminyum', 'Silisyum, fosfor, kükürt', 'Fosfor, kükürt, klor'], 'Al metal, Si yarı metal, P ametaldir; 3. periyotta geçiş alüminyumla silisyum arasında olur.'),
  ('Sodyum oksidin (Na₂O) suyla tepkimesi bazik, kükürt trioksidin (SO₃) suyla tepkimesi asidik çözelti verir. Bu farkı periyodik açıdan en iyi açıklayan hangisidir?', 'Elementin elektronegatifliği arttıkça oksidinin asidik karakterinin artması', ['Sodyumun kükürtten daha ağır olması', 'Oksijen sayısı azaldıkça oksidin asitleşmesi', 'Kükürt oksidin iyonik, sodyum oksidin ise kovalent ve moleküler bir yapıda olması'], 'Elektropozitif metallerin oksitleri O²⁻ iyonu vererek baz oluşturur; elektronegatif ametallerin oksitleri suyla oksiasit oluşturur.'),
  ('Hidrojenin metallerle iyonik hidrür oluşturması en çok hangi elementlerde görülür?', '1. ve 2. grubun etkin metallerinde', ['Soy gazlarda', 'Halojenlerde', 'Platin grubu metallerinde ve altında'], 'Hidrojenden çok daha elektropozitif olan alkali ve toprak alkali metaller hidrojene elektron vererek H⁻ içeren tuz benzeri hidrürler oluşturur.'),
  ('3. periyot elementlerinin erime noktaları sodyumdan argona doğru nasıl bir değişim gösterir?', 'Silisyuma kadar artar, sonra büyük bir düşüşle azalır', ['Düzenli olarak artar ve argonda en yüksek olur', 'Düzenli olarak azalır', 'Sekiz elementte de yaklaşık aynı kalır'], 'Na, Mg, Al metalik bağla, Si dev kovalent ağla erime noktasını yükseltir; P₄, S₈, Cl₂ ve Ar ise zayıf moleküller arası kuvvetlerle düşük erime noktalıdır.'),
  ('3. periyot elementlerinin oksitlerinde en yüksek yükseltgenme basamağı sodyumdan klora doğru nasıl değişir?', '+1\'den +7\'ye doğru bir bir artar', ['Yedi elementte de +2 olarak sabit kalır', '+7\'den +1\'e doğru azalır', 'Yalnız çift sayılı değerler alır'], 'Na₂O (+1), MgO (+2), Al₂O₃ (+3), SiO₂ (+4), P₄O₁₀ (+5), SO₃ (+6), Cl₂O₇ (+7): en yüksek basamak değerlik elektron sayısına eşittir.'),
  ('Ametallerin bileşiklerinde alabileceği en düşük (en eksi) yükseltgenme basamağı genellikle nasıl bulunur?', 'Grup numarasından 18 çıkarılarak', ['Grup numarasına 8 eklenerek', 'Periyot numarasıyla grup numarası çarpılarak', 'Atom numarası ikiye bölünerek'], 'Örneğin fosfor (15. grup) için 15 − 18 = −3, kükürt için −2, klor için −1 bulunur.'),
  ('Karbonun (14. grup) bileşiklerinde görülebilecek en düşük yükseltgenme basamağı hangisidir ve bu basamak hangi bileşikte görülür?', '−4; metanda', ['−2; karbon monoksitte', '+4; karbon dioksitte', '−1; karbon tetraklorürde'], 'Karbon hidrojenden daha elektronegatif olduğu için CH₄\'te dört bağ elektron çiftini de kendine sayar ve −4 olur.'),
  ('Berilyum ile alüminyum farklı gruplarda olduğu hâlde çapraz ilişki nedeniyle benzer davranır. Aşağıdakilerden hangisi bu benzerliğe örnektir?', 'İkisinin de oksit ve hidroksitlerinin amfoter olması', ['İkisinin de oda sıcaklığında sıvı olması', 'İkisinin de soy gaz bileşiği oluşturması', 'İkisinin de bileşiklerinde yalnızca +1 yükseltgenme basamağını alması'], 'Be(OH)₂ ve Al(OH)₃ hem asitlerde hem kuvvetli bazlarda çözünür; ayrıca BeCl₂ ve AlCl₃ belirgin kovalent karakter taşır.'),
  ('Bor ve silisyum arasındaki çapraz ilişkiye uygun olarak hangisi iki element için de doğrudur?', 'Oksitleri asidik karakterli, cam oluşturabilen katılardır', ['İkisi de alkali metaldir', 'İkisi de suyla şiddetle tepkimeye girip hidrojen açığa çıkarır', 'Oksitleri suda çözünerek kuvvetli baz oluşturur ve çözeltiyi kayganlaştırır'], 'B₂O₃ ve SiO₂ ağ yapılı asidik oksitlerdir ve ikisi de cam yapımında kullanılır; iki element de yarı metaldir.'),
  ('Periyodik sistemin blokları ele alındığında en fazla elemente sahip blok hangisidir?', 'd bloku (40 element)', ['s bloku (14 element)', 'p bloku (36 element)', 'f bloku (28 element)'], '4. ile 7. periyotlar arasında her periyotta 10 d bloku elementi vardır: 4 × 10 = 40. Dört blok toplamı 14 + 36 + 40 + 28 = 118\'dir.'),
  ('Döbereiner\'in üçlülerinden biri kalsiyum (40,1), stronsiyum (87,6) ve baryumdur (137,3). Üçlüler kuralına göre stronsiyumun atom kütlesi için tahmin edilen değer ile gerçek değer arasındaki fark yaklaşık kaçtır?', '1,1', ['0,1', '4,6', '11,0'], 'Kalsiyum ve baryumun ortalaması (40,1 + 137,3) / 2 = 88,7\'dir; gerçek değer 87,6 olduğundan fark yaklaşık 1,1\'dir.'),
  ('İnsan vücudunda atom sayısı bakımından en bol bulunan element hangisidir?', 'Hidrojen', ['Oksijen', 'Karbon', 'Kalsiyum'], 'Kütlece oksijen birinci sıradadır; ancak hafif hidrojen atomları sayıca vücuttaki atomların yaklaşık %60\'ını oluşturur.'),
  ('İnsan vücudunda kütlece en bol bulunan metal hangisidir?', 'Kalsiyum', ['Demir', 'Sodyum', 'Potasyum'], 'Yetişkin bir insanda yaklaşık 1 kg kalsiyum bulunur ve büyük kısmı kemik ve dişlerdedir.'),
  ('Çocukluk döneminde içme suyuyla aşırı florür alınmasının dişlerde yol açtığı lekelenme ve beneklenme durumuna ne ad verilir?', 'Diş florozisi', ['Diş çürüğü', 'Diş taşı', 'Diş eti iltihabı'], 'Florür az miktarda mineyi güçlendirir; ancak diş gelişimi sırasında fazlası minede beyaz ya da kahverengi lekelere yol açar.'),
  ('Cıvanın başlıca cevheri olan zincifre (HgS) havada ısıtıldığında hangi ürünler oluşur?', 'Cıva buharı ve kükürt dioksit', ['Cıva oksit ve hidrojen', 'Saf kükürt ve cıva klorür', 'Cıva sülfat, karbon dioksit ve az miktarda su buharı'], 'HgS + O₂ → Hg + SO₂ tepkimesiyle cıva buhar olarak ayrılır ve yoğunlaştırılarak toplanır.'),
  ('Beyaz fosfor sanayide hangi işlemle elde edilir?', 'Fosfat kayasının kum ve kokla elektrik fırınında ısıtılması', ['Deniz suyunun elektrolizi', 'Havanın sıvılaştırılıp damıtılması', 'Hayvan kemiklerinin suda saatlerce kaynatılması, süzülmesi ve süzüntünün kurutulması'], 'Yaklaşık 1500 °C\'de silis kalsiyumu cüruf olarak bağlar, karbon fosfatı indirger; fosfor buharı yoğunlaştırılarak toplanır.'),
  ('Günümüzde hidrojen gazının sanayide en çok üretildiği yöntem hangisidir?', 'Doğal gazın su buharıyla yüksek sıcaklıkta tepkimesi', ['Suyun güneş ışığında kendiliğinden ayrışması', 'Metallerin asitlerle tepkimesi', 'Havanın sıvılaştırılıp damıtılması ve hidrojenin diğer gazlardan kaynama noktasıyla ayrılması'], 'CH₄ + H₂O → CO + 3H₂ tepkimesi nikel katalizörle gerçekleştirilir; elektrolizle üretim toplamın küçük bir kısmıdır.'),
  ('Kalayın başlıca cevheri olan kasiteritin formülü hangisidir?', 'SnO₂', ['SnS', 'SnCl₂', 'Sn₃(PO₄)₂'], 'Kasiterit kalay(IV) oksittir; karbonla indirgenerek metal kalay elde edilir.'),
  ('Çinkonun en önemli cevheri olan sfaleritin (çinko blendi) formülü hangisidir?', 'ZnS', ['ZnO', 'ZnCO₃', 'ZnCl₂'], 'Sfalerit çinko sülfürdür; kavrulup ZnO\'ya çevrildikten sonra indirgenir ya da çözülüp elektroliz edilir.'),
  ('Bulut tohumlama denemelerinde gümüş iyodürün kullanılmasının nedeni hangisidir?', 'Kristal yapısı buza benzediği için su damlacıklarının donmasına çekirdek oluşturması', ['Bulutları ısıtarak buharlaştırması', 'Yağmur damlalarını gümüş rengine boyaması', 'Havadaki azotu suya dönüştürmesi ve böylece bulutların içindeki su miktarını kendiliğinden artırması'], 'AgI kristal örgüsünün boyutları buz kristaline yakındır; aşırı soğumuş damlacıklar onun üzerinde buz kristalleri oluşturur.'),
  ('Krom metalinin ve paslanmaz çelik için ferrokrom alaşımının elde edildiği başlıca cevher hangisidir?', 'Kromit (FeCr₂O₄)', ['Boksit (Al₂O₃·nH₂O)', 'Hematit (Fe₂O₃)', 'Kriyolit (Na₃AlF₆)'], 'Kromit demir-krom oksit mineralidir; karbonla indirgenerek doğrudan ferrokrom elde edilir.'),
  ('Henry Moseley atom numarasının gerçek anlamını hangi ölçümlerden yararlanarak ortaya koymuştur?', 'Elementlerin yaydığı karakteristik X ışınlarının frekanslarından', ['Elementlerin yoğunluklarından', 'Gazların difüzyon hızlarından', 'Elementlerin alev renklerinden, kaynama noktalarından ve oksitlerinin formüllerinden'], 'Moseley, X ışını frekansının karekökünün atom numarasıyla doğru orantılı arttığını gösterdi; bu, atom numarasının çekirdek yükü olduğunu kanıtladı.'),
  ('Atom numarası kavramını deneysel olarak temellendiren genç İngiliz fizikçi Henry Moseley 1915\'te nerede hayatını kaybetmiştir?', 'Çanakkale (Gelibolu) cephesinde', ['Verdun Muharebesi\'nde', 'Bir laboratuvar patlamasında', 'Titanik gemisinin Atlas Okyanusu\'nda batmasında'], 'Moseley Birinci Dünya Savaşı\'nda gönüllü olarak katıldığı Gelibolu seferinde 27 yaşında öldü.'),
  ('Mendeleyev 1869\'da tablosunu oluştururken yaklaşık kaç element biliniyordu?', '63', ['92', '118', '30'], 'Mendeleyev tablosuna o dönem bilinen yaklaşık 63 elementi yerleştirdi ve bilinmeyenler için boşluk bıraktı.'),
  ('Platin adı İspanyolca \'platina\' sözcüğünden gelir. Bu sözcük hangi anlamı taşır?', 'Küçük gümüş', ['Ağır altın', 'Beyaz taş', 'Parlak su damlası'], 'İspanyollar Güney Amerika\'da altınla birlikte bulunan bu beyaz metali önce değersiz bir gümüş türü sandılar.'),
  ('Hidrojenin ağır izotopu döteryumu 1931\'de bulan ve bu çalışmayla 1934 Nobel Kimya Ödülü\'nü alan bilim insanı kimdir?', 'Harold Urey', ['Ernest Rutherford', 'James Chadwick', 'Niels Bohr'], 'Urey sıvı hidrojenin dikkatli buharlaştırılmasıyla ağır izotopu zenginleştirip tayf çizgileriyle tanımladı.'),
  ('Sıvı hidrojenin sıvı oksijenle birlikte bazı roket motorlarında yakıt olarak kullanılmasının en önemli üstünlüğü hangisidir?', 'Birim kütle başına çok yüksek enerji vermesi', ['Oda sıcaklığında sıvı kalması', 'Yanma ürününün katı olması', 'Yoğunluğunun sudan çok büyük olması ve küçük depolara sığması'], 'H₂ kütlesine göre en fazla enerji veren kimyasal yakıttır; yanma ürünü yalnızca sudur. Dezavantajı çok düşük sıcaklıkta ve büyük hacimde saklanmasıdır.'),
  ('Oda koşullarında en düşük yoğunluklu gaz olan hidrojen için aşağıdaki güvenlik özelliklerinden hangisi doğrudur?', 'Havayla geniş bir oran aralığında patlayıcı karışım oluşturur', ['Hiçbir koşulda yanmaz', 'Havadan ağır olduğu için yere çöker', 'Renkli ve keskin kokulu olduğu için sızıntısı kolayca fark edilir'], 'Hidrojen havayla hacimce yaklaşık %4–75 aralığında tutuşabilir; renksiz ve kokusuz olduğundan sızıntı algılayıcılar gerekir.'),
  ('Kobaltı 1735 civarında yeni bir metal olarak tanımlayan Georg Brandt\'ın önemi hangisidir?', 'Antik Çağ\'dan sonra bulucusu bilinen ilk metali tanımlamış olması', ['Periyodik tabloyu ilk kez çizmiş olması', 'İlk soy gazı bulmuş olması', 'Atom numarasını tanımlamış ve X ışınlarıyla ölçmüş olması'], 'Brandt, mavi cam renginin bizmuttan değil yeni bir metalden geldiğini gösterdi; kobalt bulucusu bilinen ilk metal kabul edilir.'),
  ('IUPAC\'ın 2016\'da 113, 115, 117 ve 118 numaralı elementlerin adlarını onaylamasıyla periyodik sistemde ne gerçekleşmiştir?', 'Yedinci periyodun bütün kutuları adlandırılmış elementlerle doldu', ['Sekizinci periyot tamamlandı', 'Lantanitler tablodan çıkarıldı', 'Soy gazlar 1. gruba taşındı ve hidrojen 18. gruba yerleştirildi'], 'Nihonyum, moskovyum, tennesin ve oganessonun adlandırılmasıyla 1\'den 118\'e kadar bütün elementler kalıcı ad aldı.'),
  ('Mendeleyev\'in tablosunda grupların belirlenmesinde kullandığı önemli ölçütlerden biri hangisidir?', 'Elementlerin oksit ve hidrürlerinin formül türleri', ['Elementlerin renkleri', 'Elementlerin keşif yılları', 'Elementlerin bulunduğu ülkeler, maden yatakları ve cevherlerin çıkarılma yöntemleri'], 'Mendeleyev her grubu R₂O, RO, R₂O₃, RO₂ gibi ortak oksit formülleriyle tanımladı; bu, değerliğin periyodikliğini yansıtıyordu.'),
  ('Periyodik sistem üzerine çalışmalarıyla tanınan Dmitri Mendeleyev için hangisi doğrudur?', 'Nobel Ödülü almadan 1907\'de öldü', ['İlk Nobel Kimya Ödülü\'nü aldı', 'Periyodik tabloyu atom numarasına göre düzenledi', 'Soy gazları kendisi keşfetti'], 'Mendeleyev 1906\'da Nobel için aday gösterildi ama ödül Moissan\'a verildi; ertesi yıl öldü.'),
  ('Çinko bileşiklerinin (örneğin ZnSO₄ ve ZnCl₂) çözeltilerinin renksiz olmasının nedeni hangisidir?', 'Zn²⁺\'nın d alt katmanı dolu (d¹⁰) olduğundan d–d geçişi olamaması', ['Çinkonun bir ametal olması', 'Zn²⁺ iyonunun hiç elektron taşımaması', 'Çinko tuzlarının suda hiç çözünmemesi ve çözeltide yalnız su moleküllerinin kalması'], 'Renk, kısmen dolu d orbitalleri arasında görünür ışık soğurulmasıyla oluşur; d¹⁰ iyonlarda bu geçiş olanaksızdır.'),
  ('Skandiyum(III) iyonu (Sc³⁺) bir geçiş metali iyonu olduğu hâlde bileşikleri genellikle renksizdir. Bunun nedeni hangisidir?', 'Sc³⁺ iyonunda hiç d elektronu bulunmaması', ['Sc³⁺\'nın d alt katmanının tamamen dolu olması', 'Skandiyumun soy gaz olması', 'Sc³⁺ iyonunun mıknatıslığının çok güçlü olması ve ışığı yansıtması'], 'Skandiyum üç değerlik elektronunu verince [Ar] dizilimine ulaşır; d⁰ iyonlarda d–d geçişi olmaz.'),
  ('Çinkonun bileşiklerinde neredeyse yalnızca +2 yükseltgenme basamağında bulunmasının nedeni hangisidir?', 'İki 4s elektronunu verdikten sonra kalan 3d¹⁰ diziliminin çok kararlı olması', ['Çinkonun yalnız iki elektronu bulunması', 'Çinkonun ametal olması', 'Çinkonun +1 basamağının soy gaz dizilimi vermesi ve en kararlı basamak olması'], 'Dolu d alt katmanından elektron koparmak çok enerji gerektirir; bu nedenle Zn³⁺ bilinmez.'),
  ('Osmiyum tetroksitte (OsO₄) osmiyumun yükseltgenme basamağı kaçtır?', '+8', ['+4', '+6', '+2'], 'Dört oksijen toplam −8 yük getirir; nötr molekülde osmiyum +8 olmalıdır. Bu, kararlı bileşiklerde görülen en yüksek basamaklardan biridir.'),
  ('Bilinen kararlı nötr bileşiği bulunmayan iki soy gaz hangileridir?', 'Helyum ve neon', ['Kripton ve ksenon', 'Argon ve radon', 'Ksenon ve radon'], 'He ve Ne en yüksek iyonlaşma enerjili, en küçük soy gazlardır; Kr ve Xe ise flor ve oksijenle bileşikler oluşturur.'),
  ('Çamaşır deterjanlarında suyu yumuşatmak ve sanayide katalizör olarak kullanılan, düzenli gözenekli alüminosilikat mineraller hangileridir?', 'Zeolitler', ['Feldspatlar', 'Mikalar', 'Kalsitler'], 'Zeolit iskeletindeki boşluklar Ca²⁺ ve Mg²⁺ iyonlarını Na⁺ ile değiştirir ve belirli büyüklükteki molekülleri seçerek tutar.'),
  ('Ksenonun flor ile oluşturduğu XeF₂, XeF₄ ve XeF₆ bileşiklerinde ksenonun yükseltgenme basamakları sırasıyla hangisidir?', '+2, +4, +6', ['−2, −4, −6', '+1, +2, +3', '+8, +4, +2'], 'Flor her bileşikte −1 olduğundan ksenon, bağlı flor sayısı kadar artı basamak alır.'),
  ('Manganın en kararlı iki oksidi arasında yer alan, alkalin pillerde ve laboratuvarda katalizör olarak kullanılan siyah-kahverengi katı hangisidir?', 'MnO₂', ['MnO', 'Mn₂O₇', 'KMnO₄'], 'MnO₂\'de mangan +4 basamağındadır; H₂O₂\'nin ayrışmasını hızlandırır ve klorun laboratuvarda elde edilmesinde yükseltgen olarak kullanılır.'),
  ('Titanyumun bileşiklerinde en kararlı yükseltgenme basamağı hangisidir ve bunun nedeni nedir?', '+4; dört değerlik elektronunu verince soy gaz dizilimine ulaşması', ['+1; tek s elektronunu vermesi', '+2; d alt katmanının tamamen dolması', '+7; bütün elektronlarını vererek çekirdeğe yakın iç katmanları da boşaltması'], 'Ti: [Ar] 4s² 3d². Ti⁴⁺ argon dizilimindedir; TiO₂ ve TiCl₄ en yaygın bileşiklerdir.'),
  ('Geçiş metallerinin genel olarak ana grup metallerinden daha yüksek yoğunluklu ve daha yüksek erime noktalı olmasının nedeni hangisidir?', 'Küçük atom yarıçapları ve metalik bağa d elektronlarının da katılması', ['Tümünün radyoaktif olması', 'Daha az elektron taşımaları', 'İyonik bağla bağlanmaları ve kristallerinde yalnız katyon bulunması'], 'd elektronları metalik bağı güçlendirir; atomlar sıkı paketlenir ve kütle küçük hacimde toplanır.'),
  ('Altın bileşiklerinde en sık görülen iki yükseltgenme basamağı hangileridir?', '+1 ve +3', ['+2 ve +4', '−1 ve +5', '+4 ve +6'], 'Altın klorür kompleksleri AuCl₂⁻ (+1) ve AuCl₄⁻ (+3) biçimindedir; kral suyunda +3 basamağına yükseltgenir.'),
  ('Kanser tedavisinde kullanılan kobalt-60 yapay bir izotoptur. Doğadaki kobalt kaç kararlı izotoptan oluşur?', '1', ['2', '4', '0'], 'Doğal kobaltın tamamı kobalt-59\'dur; Co-60 yapay olarak nükleer reaktörlerde üretilir.'),
  ('Geçiş metallerinin pek çoğunun mıknatısa çekilmesine (paramanyetiklik) yol açan özellik hangisidir?', 'Eşleşmemiş d elektronları bulundurmaları', ['Çekirdeklerindeki nötron fazlalığı', 'Bütün elektronlarının eşleşmiş olması', 'Yüksek yoğunluklu olmaları ve ağır atomlardan oluşmaları'], 'Eşleşmemiş elektronların spinleri manyetik moment oluşturur; d¹⁰ iyonları (Zn²⁺ gibi) diyamanyetiktir.'),
  ('Astatin çok az miktarda elde edilebildiği için özelliklerinin çoğu tahmin edilir. Periyodik eğilimlere göre astatin için hangisi beklenir?', 'İyottan daha koyu renkli bir katı olması ve iyottan daha az yükseltgen olması', ['Oda koşullarında renksiz bir gaz olması', 'Flordan daha güçlü bir yükseltgen olması', 'Suyla şiddetle tepkimeye girip hidrojen açığa çıkaran, yumuşak ve gümüş renkli bir alkali metal olması'], 'Halojenlerde aşağı inildikçe renk koyulaşır, erime noktası artar ve yükseltgen güç azalır.'),
  ('Henüz elde edilememiş 119 numaralı elementin periyodik sistemdeki yeri ve davranışı için en makul tahmin hangisidir?', '8. periyodun başında, 1. grupta yer alan bir alkali metal olması', ['7. periyotta bir soy gaz olması', '8. periyotta bir halojen olması', 'Lantanitler arasında yer alan ve +3 iyonu oluşturan bir f bloku elementi olması'], 'Oganesson (118) 7. periyodu tamamlar; bir sonraki element yeni bir s alt katmanını (8s) doldurmaya başlar.'),
  ('Uzay araçlarında astronotların soluduğu havadaki karbon dioksiti tutmak için lityum hidroksit kullanılmasının, ağır alkali hidroksitlere göre üstünlüğü hangisidir?', 'Kütle başına daha fazla CO₂ tutabilmesi', ['Oksijen üretmesi', 'Hiç tepkimeye girmemesi', 'Radyoaktif olması ve kozmik ışınları soğurması'], 'LiOH\'nin mol kütlesi küçüktür (yaklaşık 24 g/mol); uzay araçlarında her gram önemli olduğundan hafif soğurucu tercih edilir.'),
  ('Petrol rafinerileri ve patlayıcı ortamlarda berilyum-bakır alaşımından yapılmış el aletlerinin kullanılmasının nedeni hangisidir?', 'Çelik aletler gibi kıvılcım çıkarmamaları', ['Daha ucuz olmaları', 'Mıknatısa güçlü biçimde çekilmeleri', 'Radyoaktif olup ortamdaki yanıcı gazı nötrleştirmeleri'], 'Berilyum-bakır sert ve dayanıklıdır, ancak çarpma ve sürtünmede tutuşturucu kıvılcım oluşturmaz.'),
  ('Pencere camı üretiminde kullanılan \'float\' (yüzdürme) yönteminde erimiş cam hangi metalin erimiş hâli üzerinde yüzdürülerek pürüzsüz ve düz hâle getirilir?', 'Kalay', ['Cıva', 'Kurşun', 'Alüminyum'], 'Erimiş kalay geniş bir sıcaklık aralığında sıvı kalır, camdan yoğundur ve camla karışmaz; bu yüzden düzgün bir yüzey sağlar.'),
  ('X elementi 3. periyot 1. grupta, Y elementi 3. periyot 17. gruptadır. Bu elementler için hangisi yanlıştır?', 'Y\'nin atom yarıçapı X\'inkinden büyüktür', ['X\'in iyonlaşma enerjisi Y\'ninkinden küçüktür', 'Y\'nin elektronegatifliği X\'inkinden büyüktür', 'X metal, Y ametaldir'], 'Aynı periyotta sağdaki element (Y: klor) daha küçüktür; diğer ifadeler doğrudur.'),
  ('Bir elementin atom numarası 38\'dir. Bu elementin özellikleri için hangi tahmin doğrudur?', 'Bileşiklerinde +2 yükseltgenme basamağı alan bir toprak alkali metaldir', ['Bileşiklerinde −2 basamağı alan bir kalkojendir', 'Oda koşullarında gaz hâlinde bir soy gazdır', '+3 basamağı alan, kimyasal özellikleri komşularına çok benzeyen bir lantanittir'], 'Z = 36 kriptondan sonra gelen 37 rubidyum ve 38 stronsiyum 5. periyodun s bloku elementleridir; Sr 2. gruptadır.'),
  ('Bir elementin değerlik katmanı dizilimi 4s² 3d¹⁰ 4p¹ biçiminde bitiyor. Bu elementin grubu ve bileşiklerinde en sık aldığı iyon yükü hangisidir?', '13. grup; +3', ['3. grup; +1', '11. grup; +2', '15. grup; −3'], 'p bloku için grup = 10 + s + p elektronları = 13; element galyumdur ve üç elektronunu vererek Ga³⁺ oluşturur.'),
  ('Oda koşullarında gaz hâlinde bulunan elementler arasında yoğunluğu en yüksek olan hangisidir?', 'Radon', ['Ksenon', 'Klor', 'Kripton'], 'Radonun mol kütlesi yaklaşık 222 g/mol\'dür; bu nedenle aynı koşullarda bilinen en yoğun gaz elementtir ve bodrumlarda birikebilir.'),
  ('Şarapların bozulmasını önlemek için geleneksel olarak eklenen ve E220 koduyla bilinen kükürt bileşiği hangisidir?', 'Kükürt dioksit', ['Hidrojen sülfür', 'Kükürt hekzaflorür', 'Karbon disülfür'], 'SO₂ mikroorganizmaların üremesini ve şarabın yükseltgenmesini engeller; bazı kişilerde alerjik tepkiye yol açabilir.'),
  ('Elmasın yüksek parıltısının (ateş ve ışıltı) temel optik nedeni hangisidir?', 'Kırıcılık indisinin çok yüksek olması', ['Kendi ışığını üretmesi', 'Metal gibi serbest elektron taşıması', 'Radyoaktif ışıma yapması ve içinde parlayan çekirdekler bulunması'], 'Yüksek kırıcılık, ışığın taşın içinde tam yansımalarla kalmasını ve renklere ayrılmasını sağlar.'),
  ('Lidya Krallığı\'nda basılan ilk madeni paralar, doğada kendiliğinden oluşan hangi alaşımdan yapılmıştı?', 'Elektrum (altın-gümüş alaşımı)', ['Bronz (bakır-kalay alaşımı)', 'Pirinç (bakır-çinko alaşımı)', 'Çelik (demir-karbon alaşımı)'], 'Elektrum, Gediz ve Paktolos (Sart Çayı) gibi akarsuların kumlarında bulunan doğal bir altın-gümüş alaşımıdır.'),
  ('Isıyla çok az genleşen ve hassas ölçü aletlerinde kullanılan \'invar\' alaşımı hangi iki metalden oluşur?', 'Demir ve nikel', ['Bakır ve çinko', 'Alüminyum ve magnezyum', 'Kurşun ve kalay'], 'Yaklaşık %36 nikel içeren demir alaşımı invar, oda sıcaklığı civarında neredeyse hiç genleşmez; Charles Guillaume bu buluşla 1920 Nobel Fizik Ödülü\'nü aldı.'),
  ('Tarihî kalay alaşımı olan \'kalay-kurşun\' sofra eşyalarının (pewter) yerini günümüzde kurşunsuz alaşımların almasının nedeni hangisidir?', 'Kurşunun yiyecek ve içeceklere geçerek zehirlenmeye yol açabilmesi', ['Kurşunun çok pahalı olması', 'Kalayın havada patlayıcı olması', 'Kurşunun oda sıcaklığında buharlaşıp yiyeceğe tat vermesi ve rengini değiştirmesi'], 'Asitli yiyecekler kurşunu çözebilir; bu yüzden modern pewter kalaya bakır ve antimon katılarak yapılır.'),
  ('Doğal uranyumun yaklaşık yüzde kaçı bölünebilir uranyum-235 izotopudur?', '0,7', ['99,3', '50', '3'], 'Doğal uranyumun yaklaşık %99,3\'ü U-238, yalnızca %0,7\'si U-235\'tir; reaktör yakıtı için U-235 oranı genellikle %3–5\'e zenginleştirilir.'),
  ('19. yüzyılın sonlarında gaz lambalarının ışığını parlatan \'Welsbach gömleği\'nde hangi aktinitin oksidi kullanılmıştır?', 'Toryum', ['Plütonyum', 'Neptünyum', 'Amerikyum'], 'Toryum dioksit (az miktar seryum oksitle) ısıtılınca parlak beyaz ışık yayar; toryumun radyoaktifliği nedeniyle bugün kullanımı azalmıştır.'),
  ('1987\'de sıvı azot sıcaklığının üzerinde süperiletkenlik gösterdiği bulunan YBa₂Cu₃O₇ seramiğinde hangi 3. grup elementi bulunur?', 'İtriyum', ['Skandiyum', 'Lantan', 'Aktinyum'], 'İtriyum-baryum-bakır oksit (YBCO) yaklaşık 92 K\'de süperiletken olur; böylece pahalı sıvı helyum yerine sıvı azotla soğutulabilir.'),
  ('Lantanitler serisinin son üyesi olan ve 4f alt katmanı tamamen dolu olan element hangisidir?', 'Lutesyum', ['Lantan', 'İterbiyum', 'Seryum'], 'Lutesyumun (Z = 71) dizilimi [Xe] 6s² 4f¹⁴ 5d¹\'dir; Paris\'in Latince adı Lutetia\'dan adlandırılmıştır.'),
  ('Lord Rayleigh, havadan elde ettiği azotun kimyasal yollarla üretilen azottan biraz daha yoğun olduğunu fark etti. Bu küçük farkın açıklanması hangi buluşa yol açmıştır?', 'Havadaki azotun içinde gizli kalmış argonun keşfine', ['Azotun iki atomlu olduğunun anlaşılmasına', 'Oksijenin keşfine', 'Havanın tamamen azottan oluştuğunun ve başka hiçbir gaz içermediğinin kanıtlanmasına'], 'Havadan ayrılan \'azot\' yaklaşık %1 oranında daha ağır argon içeriyordu; Rayleigh ve Ramsay 1894\'te bu yeni gazı ayırdı.'),
  ('Metallerin asitlerle tepkimesinden çıkan \'yanıcı havayı\' 1766\'da ayrı bir madde olarak tanımlayan ve bugün hidrojen dediğimiz gazı inceleyen bilim insanı kimdir?', 'Henry Cavendish', ['Joseph Priestley', 'Humphry Davy', 'Michael Faraday'], 'Cavendish yanıcı havanın yoğunluğunu ölçtü ve yandığında su oluştuğunu gösterdi; adı daha sonra Lavoisier tarafından konuldu.'),
  ('Azotu 1772\'de havadan ayırıp \'zararlı hava\' olarak tanımlayan İskoç bilim insanı kimdir?', 'Daniel Rutherford', ['Ernest Rutherford', 'Robert Boyle', 'John Dalton ve William Henry'], 'Daniel Rutherford, içinde hayvan solutulup mum yakılan ve CO₂\'si giderilen havanın yaşamı ve yanmayı desteklemediğini gösterdi.'),
  ('13. grubun oksitleri B₂O₃, Al₂O₃ ve Tl₂O karşılaştırıldığında asit-baz karakteri nasıl değişir?', 'B₂O₃ asidik, Al₂O₃ amfoter, Tl₂O baziktir', ['Üçü de kuvvetli baziktir', 'B₂O₃ bazik, Tl₂O asidiktir', 'Üçü de suda çözünmeyen ve hiçbir asit ya da bazla tepkimeye girmeyen nötr oksitlerdir'], 'Grupta aşağı inildikçe metalik karakter arttığından oksitler asidikten baziğe doğru değişir.'),
  ('Sodyum, magnezyum ve alüminyum gibi metallerin cevherlerinden karbonla indirgenerek değil de elektrolizle elde edilmesinin temel nedeni hangisidir?', 'Bu metallerin oksijene ve klora karbondan daha güçlü bağlanması', ['Cevherlerinin çok az bulunması', 'Bu metallerin cevherlerinin karbonla hiçbir koşulda temas ettirilememesi', 'Elektrolizin her zaman en ucuz yöntem olması'], 'Çok etkin metallerin bileşikleri karbonla indirgenemeyecek kadar kararlıdır; demir ve çinko gibi daha az etkin metaller ise karbonla indirgenir.'),
  ('Silisyumu 1824\'te saf element olarak ilk kez elde eden, selenyum, seryum ve toryumu da bulan İsveçli kimyacı kimdir?', 'Jöns Jacob Berzelius', ['Carl Wilhelm Scheele', 'Anders Celsius', 'Svante August Arrhenius'], 'Berzelius potasyum florosilikatı potasyumla indirgeyerek amorf silisyum elde etti; kimyasal simge sistemini de o önermiştir.'),
  ('Bir metalin cevherden hangi yöntemle elde edileceğini seçerken etkinlik sıralamasındaki yeri neden önemlidir?', 'Daha etkin metallerin bileşikleri daha kararlı olduğundan daha güçlü indirgeme gerektirir', ['Etkin metaller doğada hep saf bulunur', 'Etkinlik yalnız metalin rengini belirler', 'Etkin metaller ısıtılınca kendiliğinden ayrışır ve cevherden ayrılmaları için hiçbir ek işlem gerekmez'], 'Altın gibi soy metaller saf bulunur, demir gibi orta etkinlikteki metaller karbonla, alüminyum gibi çok etkin metaller elektrolizle elde edilir.'),
  ('Alüminyum, galyum, indiyum, kalay, talyum, kurşun ve bizmut gibi p blokunda yer alan metallere verilen ortak ad hangisidir?', 'Geçiş sonrası metaller', ['Toprak alkali metaller', 'Platin grubu metalleri', 'İç geçiş metalleri'], 'Bu metaller d blokunun sağında yer alır; geçiş metallerinden daha yumuşak ve daha düşük erime noktalıdırlar.'),
  ('Niyobyum, molibden, tantal, tungsten ve renyum gibi çok yüksek erime noktalı ve aşınmaya dayanıklı metallere ne ad verilir?', 'Refrakter metaller', ['Alkali metaller', 'Soy gazlar', 'Hafif metaller ve alaşımları'], 'Refrakter metallerin erime noktaları 2000 °C\'nin üzerindedir; fırın parçaları, roket memeleri ve elektrotlarda kullanılır.'),
  ('Sodyum ve potasyumdan oluşan NaK alaşımının oda sıcaklığında sıvı olması bazı reaktörlerde hangi amaçla kullanılmasını sağlamıştır?', 'Isı aktarıcı soğutucu sıvı olarak', ['Nükleer yakıt olarak', 'Radyasyon zırhı olarak', 'Su arıtmada dezenfektan ve tortu çöktürücü olarak'], 'NaK geniş bir sıcaklık aralığında sıvıdır ve ısıyı çok iyi iletir; ancak hava ve suyla şiddetli tepkimesi dikkat gerektirir.'),
  ('James Webb Uzay Teleskobu\'nun ana aynasının bölümleri hafif ve soğukta biçimini koruyan bir metalden yapılıp altınla kaplanmıştır. Bu metal hangisidir?', 'Berilyum', ['Kurşun', 'Osmiyum', 'Tungsten'], 'Berilyum çok hafif ve serttir, çok düşük sıcaklıklarda boyut değişimi azdır; altın kaplama kızılötesi ışığı iyi yansıtır.'),
  ('Yangın söndürme sprinklerlerinde tetikleyici olarak kullanılan ve 100 °C\'nin altında eriyen alaşımların (örneğin Wood metali) ana bileşeni hangi elementtir?', 'Bizmut', ['Tungsten', 'Titanyum', 'Demir'], 'Bizmut kurşun, kalay ve kadmiyumla düşük erime noktalı ötektik alaşımlar oluşturur; ısı yükselince alaşım erir ve su akışı başlar.'),
  ('Fosfor pentoksidin (P₄O₁₀) laboratuvarda gazları ve çözücüleri kurutmak için kullanılmasının nedeni hangisidir?', 'Suyu çok güçlü biçimde bağlayarak fosforik aside dönüşmesi', ['Su ile hiç tepkimeye girmemesi', 'Suyu oksijene dönüştürmesi', 'Gazları soğutup yoğunlaştırması ve oluşan sıvıyı kabın dışına itmesi'], 'P₄O₁₀ bilinen en etkili kurutuculardan biridir; suyla ekzotermik tepkimeyle H₃PO₄ oluşturur.'),
  ('Demir, kobalt ve nikelin periyodik sistemde yan yana yer alıp benzer özellikler göstermesi nedeniyle eskiden bu üç elemente verilen ad hangisidir?', 'Demir üçlüsü', ['Platin grubu', 'Soy metaller', 'Alkali üçlüsü'], 'Fe, Co ve Ni\'nin yoğunlukları, erime noktaları ve ferromanyetiklikleri birbirine yakındır; eski tablolarda VIII. grupta birlikte gösterilirlerdi.'),
  ('Metallerin çoğu gümüşi-gri renkte görünür. Saf hâlde belirgin biçimde renkli görünen üç metal hangileridir?', 'Bakır, altın ve sezyum', ['Demir, nikel ve kobalt', 'Alüminyum, magnezyum ve çinko', 'Kurşun, kalay ve cıva'], 'Bakır kızıl, altın sarı, sezyum ise soluk altın sarısı renktedir; diğer metaller görünür ışığın tamamını benzer biçimde yansıtır.'),
  ('Morötesi ışık altında parlak yeşil ışıldayan ve \'vazelin camı\' da denen sarı-yeşil camın rengini veren radyoaktif element hangisidir?', 'Uranyum', ['Kobalt', 'Bakır', 'Krom'], 'Cama katılan az miktarda uranyum oksit sarı-yeşil renk ve güçlü floresans verir.'),
  ('Gösteri fişeklerinde elde edilmesi en zor renk sayılan mavi, çoğunlukla hangi metalin klorürlü bileşikleriyle sağlanır?', 'Bakır', ['Stronsiyum', 'Baryum', 'Sodyum'], 'Bakır(I) klorür türleri alevde mavi ışık yayar; mavi, havai fişeklerde elde edilmesi en zor renklerden biridir.'),
  ('Wollaston\'ın 1803\'te platin cevherinden ayırdığı ve hidrojen emme yeteneğiyle bilinen paladyuma verdiği ad neye göndermedir?', 'Bir yıl önce bulunan Pallas asteroidine', ['Atina\'daki Parthenon tapınağına', 'Paladin adlı Orta Çağ şövalyelerine', 'Palau adalarına ve oradaki maden yataklarına'], 'Wollaston 1803\'te bulduğu elemente bir yıl önce keşfedilen ikinci asteroit Pallas\'ın adını verdi.'),
  ('Soy gazların atom numaraları 2, 10, 18, 36 ve 54\'tür. Bu dizinin bir sonraki üyesi olan soy gazın atom numarası kaçtır?', '86', ['72', '70', '118'], 'Ardışık soy gazlar arasındaki farklar periyot uzunluklarıdır: 8, 8, 18, 18, 32. 54 + 32 = 86 (radon).'),
  ('Kalsiyumun atom numarası 20\'dir. Periyodik sistemde kalsiyumun hemen altında yer alan elementin atom numarası kaçtır?', '38', ['28', '36', '52'], '4. periyotta 18 element bulunduğundan bir alttaki elementin atom numarası 18 fazladır: 20 + 18 = 38 (stronsiyum).'),
  ('Halojenlerin hidrojenle tepkimesi incelendiğinde hangi eğilim görülür?', 'Flor karanlıkta bile patlayarak, iyot ise ancak ısıtılınca yavaş ve tersinir biçimde tepkimeye girer', ['Dördü de aynı hızla tepkimeye girer', 'İyot en hızlı, flor en yavaş tepkimeye girer', 'Halojenlerin hiçbir üyesi hidrojenle hiçbir koşulda tepkimeye girmez ve her zaman tek başına kalır'], 'Halojenlerin etkinliği grupta aşağı doğru azalır; H–I bağı zayıf olduğundan HI oluşumu dengede kalır.'),
  ('Germanyumun atom numarası 32\'dir. Periyodik sistemde germanyumun hemen üstündeki elementin atom numarası kaçtır?', '14', ['24', '16', '22'], '3. ve 4. periyot arasında p bloku elementleri için fark 18\'dir: 32 − 18 = 14 (silisyum).'),
  ('Kükürt, selenyum ve tellürün oksijenden farklı olarak hidrojen bağı yapmayan hidrürler (H₂S, H₂Se, H₂Te) oluşturmasının nedeni hangisidir?', 'Bu atomların elektronegatifliklerinin oksijenden çok düşük ve atomlarının büyük olması', ['Bu elementlerin hidrojenle hiç bağ yapmaması', 'Hidrürlerinin iyonik olması', 'Bu elementlerin metal olması ve hidrojeni hidrür iyonu olarak bağlayarak tuz benzeri katılar oluşturması'], 'Hidrojen bağı için hidrojenin küçük ve çok elektronegatif bir atoma (N, O, F) bağlı olması gerekir.'),
  ('Bir elementin atomları büyük, iyonlaşma enerjisi düşük, elektronegatifliği küçükse bu elementin klorla oluşturacağı bileşik için en makul tahmin hangisidir?', 'Yüksek erime noktalı, iyonik bir katı olması', ['Oda sıcaklığında gaz olan kovalent bir molekül olması', 'Suyla hiç etkileşmeyen yağlı bir sıvı olması', 'Klorla hiç bileşik oluşturmaması'], 'Bu özellikler etkin bir metali tanımlar; metal klora elektron vererek NaCl ya da CsCl gibi iyonik katılar oluşturur.'),
  ('Çernobil kazasından sonra uzun yıllar toprakta kalan ve potasyuma benzediği için bitkilerce kolayca alınan radyoizotop hangisidir?', 'Sezyum-137', ['Karbon-14', 'Helyum-4', 'Kurşun-208'], 'Cs⁺ ve K⁺ aynı grupta olduğundan canlılar sezyumu potasyum gibi alır; Cs-137\'nin yarı ömrü yaklaşık 30 yıldır.'),
  ('Petrol ve doğal gaz kuyularının sondajında kullanılan çamurlara barit (BaSO₄) eklenmesinin amacı hangisidir?', 'Çamurun yoğunluğunu artırıp kuyudaki yüksek basıncı dengelemek', ['Çamuru renklendirip görünür kılmak', 'Petrolü kimyasal olarak parçalamak', 'Sondaj ucunu soğutmak için su yerine buharlaşmak'], 'Barit yaklaşık 4,5 g/cm³ yoğunlukta, suda çözünmeyen ve tepkimesiz bir mineraldir.'),
  ('Günümüzde dünyadaki elementel kükürdün büyük kısmı hangi kaynaktan elde edilir?', 'Petrol ve doğal gazın kükürtten arındırılması sırasında açığa çıkan hidrojen sülfürden', ['Volkan kraterlerinden elle toplanarak', 'Deniz suyunun buharlaştırılmasıyla', 'Havanın sıvılaştırılıp damıtılmasıyla'], 'Claus yönteminde H₂S kısmen yakılıp SO₂ ile tepkimeye sokulur ve elementel kükürt elde edilir; bu kaynak Frasch yönteminin yerini almıştır.'),
  ('103 numaralı element lavrensiyum, adını hangi buluşuyla tanınan Ernest Lawrence\'tan almıştır?', 'Siklotronun (parçacık hızlandırıcı) icadı', ['Radyoaktivitenin keşfi', 'Elektronun keşfi', 'Periyodik tablonun ilk çizimi'], 'Ağır elementlerin çoğu siklotron ve türevi hızlandırıcılarla elde edildi; Lawrence bu buluşla 1939 Nobel Fizik Ödülü\'nü aldı.'),
  ('105 numaralı dubniyum ve 115 numaralı moskovyum adlarının ortak noktası hangisidir?', 'İkisi de Rusya\'daki bir yer adından türetilmiştir', ['İkisi de bir bilim insanının soyadından gelir', 'İkisi de Yunan mitolojisinden gelir', 'İkisi de bir gezegenin adını taşır'], 'Dubniyum Dubna kentinin, moskovyum ise Moskova bölgesinin adını taşır; Dubna\'daki Birleşik Nükleer Araştırmalar Enstitüsü birçok süper ağır elementin bulunduğu yerdir.'),
  ('19. yüzyıl tiyatrolarında sahneyi aydınlatan ve İngilizcede \'ilgi odağı\' anlamına da gelen \'limelight\' ışığı hangi maddenin alevde akkor hâline getirilmesiyle elde ediliyordu?', 'Kalsiyum oksit', ['Sodyum klorür', 'Magnezyum sülfat', 'Kurşun oksit'], 'Oksihidrojen alevinde ısıtılan kireç bloğu çok parlak beyaz ışık saçar; bu kireç ışığı elektrikli ışıklardan önce sahnelerde kullanıldı.'),
  ('Bazı yüksek dayanımlı çeliklerin hidrojen ortamında zamanla çatlaması olayına ne ad verilir?', 'Hidrojen gevrekliği', ['Kalay vebası', 'Pasifleşme', 'Galvanizleme'], 'Küçük hidrojen atomları metal örgüsüne yayılıp tane sınırlarında birikir; metal sünekliğini yitirerek kırılganlaşır.'),
  ('Küçük ölçekli altın madenciliğinde cıvanın kullanılması ciddi bir çevre sorunudur. Bu yöntemde cıva hangi amaçla kullanılır?', 'Altınla amalgam oluşturup onu kumdan ayırmak', ['Altını eritip sıvılaştırmak için yakıt olarak', 'Altının rengini koyulaştırmak için', 'Altını radyoaktif yaparak izlemek için'], 'Altın cıvada çözünerek amalgam oluşturur; amalgam ısıtıldığında cıva buharlaşır ve havaya, toprağa ve suya karışır.'),
  ('Hafif uçak gövdelerinde kullanılan alüminyum-lityum alaşımlarının sağladığı başlıca üstünlük hangisidir?', 'Alaşımın yoğunluğunu düşürüp sertliğini artırması', ['Alaşımı radyoaktif yapması', 'Alaşımı oda sıcaklığında sıvılaştırması', 'Alaşımın elektriği hiç iletmemesini sağlayıp yıldırımdan koruması'], 'Lityum en hafif metaldir; az miktarı bile alüminyumun yoğunluğunu düşürür ve esneklik modülünü artırır.'),
  ('Bir elementin oksidi suda çözündüğünde çözelti bazik oluyor, elementin kendisi de elektriği iyi iletiyor ve parlak görünüyor. Bu elementin periyodik sistemde bulunması en olası bölge hangisidir?', 'Sol taraftaki s bloku', ['Sağ üstteki halojenler', '18. grup', 'Merdiven çizgisinin sağındaki ametaller'], 'Bazik oksit, metalik iletkenlik ve parlaklık tipik metal özellikleridir; bu özellikler en belirgin biçimde 1. ve 2. grup metallerinde görülür.'),
  ('Hem Cl₂ hem de Br₂ suyla kısmen tepkimeye girer. Klorlu suyun kâğıt ve kumaşları ağartması hangi türün oluşmasına bağlıdır?', 'Hipokloröz asit', ['Hidrojen gazı', 'Sodyum klorür', 'Klorat iyonu ve oksijen gazı'], 'Cl₂ + H₂O ⇌ HCl + HOCl tepkimesinde oluşan HOCl güçlü bir yükseltgendir ve boyar maddeleri renksizleştirir.'),
  ('Alüminyum ve demir aynı ortamda nemli havaya bırakılıyor. Demir paslanıp ufalanırken alüminyumun yüzeyinin korunması iki metalin hangi farkıyla açıklanır?', 'Alüminyum oksidin sıkı ve yapışık, demir oksidin ise gözenekli ve dökülen bir tabaka oluşturması', ['Alüminyumun demirden daha az etkin olması', 'Demirin oksijenle hiç tepkimeye girmemesi', 'Alüminyumun havadaki azotla koruyucu bir nitrür tabakası oluşturması ve oksijeni tamamen engellemesi'], 'Pas (sulu Fe₂O₃) gözenekli olduğu için alttaki metale nem ve oksijen ulaşmaya devam eder; Al₂O₃ ise yüzeyi tümüyle kapatır.'),
  ('Germanyum, kalay ve kurşun 14. grupta yer alır. Bu üç elementin klorürleri GeCl₄, SnCl₄ ve PbCl₂ biçiminde en kararlı olduğuna göre hangi eğilim görülür?', 'Grupta aşağı doğru +2 basamağının kararlılığı artar', ['Grupta aşağı doğru +4 basamağının kararlılığı artar', 'Üç element de yalnızca +4 basamağını alır', 'Kurşun bileşiklerinde −4 basamağını tercih eder'], 'Ağır elementlerde 6s² elektron çifti bağa katılmaya isteksizdir; bu yüzden kurşunda +2 basamağı öne çıkar.'),
  ('Çinkonun atom numarası 30\'dur. Çinko, kadmiyum ve cıva 12. grupta bu sırayla alt alta yer aldığına göre üç elementin atom numaraları hangisinde doğru verilmiştir?', 'Zn 30, Cd 48, Hg 80', ['Zn 30, Cd 40, Hg 50', 'Zn 30, Cd 46, Hg 78', 'Zn 30, Cd 62, Hg 94'], '5. periyotta 18 element bulunduğundan Cd = 30 + 18 = 48; 6. periyotta 32 element olduğundan Hg = 48 + 32 = 80.'),
];
